import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import test from 'node:test'
import { analyzeCommits } from '@semantic-release/commit-analyzer'

const config = JSON.parse(readFileSync(new URL('../../.releaserc.json', import.meta.url)))
const options = config.plugins.find(([name]) => name === '@semantic-release/commit-analyzer')[1]
const cwd = fileURLToPath(new URL('.', import.meta.url))
const analyze = messages => analyzeCommits(options, {
  cwd, commits: messages.map(message => ({ hash: '1234567', message })), logger: { log() {} },
})

for (const [message, expected] of [
  ['feat: add an option', 'minor'],
  ...['fix', 'perf', 'revert'].map(type => [`${type}: repair an option`, 'patch']),
  ...['chore', 'ci', 'docs', 'style', 'refactor', 'test', 'build'].flatMap(type => [
    [`${type}: reorganize internals`, null],
    [`${type}!: remove old configuration`, null],
    [`${type}: remove old configuration\n\nBREAKING CHANGE: old configuration is unsupported`, null],
    [`${type}!: remove old configuration\n\nBREAKING CHANGE: old configuration is unsupported`, null],
  ]),
  ...['feat', 'fix', 'unknown'].flatMap(type => [
    [`${type}!: remove old configuration`, 'minor'],
    [`${type}: remove old configuration\n\nBREAKING CHANGE: old configuration is unsupported`, 'minor'],
    [`${type}!: remove old configuration\n\nBREAKING CHANGE: old configuration is unsupported`, 'minor'],
  ]),
]) {
  test(message, async () => assert.equal(await analyze([message]), expected))
}

test('the three real imported breaking commits select minor overall', async () => {
  // Messages captured with git show -s --format=%B for f2f16319, b3e45da9, c15cbabf.
  const messages = [
    "feat(FlyView)!: replace QGCToolInsets with typed occluders\n\nQGCToolInsets flattened each Fly View widget into 12 edge distances that\nevery layer had to pass through, and the map then rebuilt rectangles from\nthem. Replace it with occluders: the actual widget rectangles.\n\n- FlyViewOccluders: one named rect per upstream widget (pipView, toolStrip,\n  topRight, bottomRight, mapScale, virtualJoystickLeft/Right) in widget\n  layer coordinates. A hidden widget collapses to a zero size rect at its\n  anchor corner, so x/y stay usable for positioning.\n- FlyViewWidgetLayer owns the occluders. FlyViewCustomLayer gets them as\n  `occluders` and reports its own controls through `customOccluders`.\n- Both map engines keep the vehicle inside the widget layer viewport and out\n  from under every occluder, recentering on the viewport center.\n  MapPositionTracker::evaluateInsetFollow becomes evaluateOccluderFollow.\n  The GeoMap engine now honors occluders too (it previously ignored the\n  widgets entirely).\n- FlyViewOccluderViewer replaces FlyViewInsetViewer as the debug overlay.\n- custom-example and the custom build docs are ported to the new API; the\n  docs page also gets its file names, capitalization and typos fixed.\n\nBREAKING CHANGE: QGCToolInsets is removed. Custom FlyViewCustomLayer\noverrides must replace parentToolInsets/totalToolInsets with the\n`occluders` input and `customOccluders` output (see custom-example).\nFlyViewWidgetLayer overrides must take `pipViewRect` and provide\n`occluders`.\n\n",
    "feat(QmlControls)!: layered window palette and refreshed control styling\n\nRework QGCPalette around a small set of semantic roles so screens get\nconsistent nested shading, one subtle border color, and two text colors:\n\n- window / windowPanel / windowCard / windowInset for nested surfaces\n- borderSubtle for container borders and dividers\n- textPrimary / textSecondary for values and captions\n- accent / accentSubtle / accentText for selection, focus and primary\n  actions (accent keeps the original #3A9BDC blue)\n\nShared controls are restyled on the new roles: buttons, delay buttons,\ncombo boxes, text fields, sliders, switches, group boxes, sidebar\nnavigation buttons and the view select dropdown all use a subtle\nborder, an inset well for inputs, and an accent outline over a faint\naccent fill for selected/pressed state. Vehicle Configure and\nApplication Settings sidebars sit in a bordered panel.\n\nAlso:\n- tighten control vertical padding (ScreenTools.controlVerticalPadding)\n- size button icons from the button height instead of the text height\n- fix QGCSlider boundary labels overlapping the handle\n- give FactTextFieldSlider a card background with inner padding\n- readable QGCTextField placeholder text\n\nBREAKING CHANGE: the palette roles windowShade, windowShadeDark,\nwindowShadeLight, text, button, buttonBorder, buttonText,\nbuttonHighlight, buttonHighlightText, primaryButton, primaryButtonText,\ntextField, textFieldText, textFieldErrorText and groupBorder are\nremoved. Custom builds that reference them in QML or override them in\nQGCCorePlugin::paletteOverride must migrate:\nwindowShadeDark -> windowPanel, windowShade/button -> windowCard,\ntextField -> windowInset, groupBorder/buttonBorder -> borderSubtle,\ntext/buttonText/textFieldText -> textPrimary,\nbuttonHighlight/primaryButton -> accent,\nbuttonHighlightText/primaryButtonText -> accentText,\ntextFieldErrorText -> errorText. windowShadeLight has no direct\nreplacement; use textSecondary for muted foreground or windowCard for\nfills.\n\n",
    "fix(Video): harden and restructure the GStreamer receiver, sink, zero-copy paths and CMake (#15304)\n\n* fix(HwBuffers): keep frame-texture resources until bundle destruction\n\nQt's QVideoFrameTexturePool calls onFrameEndInvoked() on the current\nbundle after every window frame and keeps it bound to the material until\nits slot is reused. Releasing the source sample (base class), the\nDMABuf GL texture names, the imported Vulkan VkImage/VkDeviceMemory and\nthe IOSurface CVMetalTextureRefs from that hook made every UI repaint\nbetween video frames sample freed resources (deleted GL names render\ngreen, Vulkan/Metal wrappers dangle, the decoder may recycle the shown\nbuffer). All of them are now released only from the bundle destructor.\n\nAlso fix the texture(plane) bounds check so an out-of-range uint plane\ncan no longer wrap negative and index past the plane array.\n\nFixes review H#1, S#22.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(HwBuffers): fix DMABuf producer sync, EGL latches and Vulkan import\n\n- Producer barrier (H#9): the LINEAR \"EGL fence\" tier fenced Qt's own\n  context, so it blocked the render thread every frame without any\n  ordering against the VA-API/V4L2 producer, and it suppressed the mmap\n  barrier that did wait. It is dropped. When the producer's dma-buf\n  fence can't be imported for a GPU-side wait, each plane fd is poll()ed\n  instead (POLLIN, bounded at 100 ms, recorded as a CPU-side wait),\n  which waits on the same implicit write fences without mmapping every\n  plane or triggering exporter cache maintenance.\n- EGL_BAD_MATCH latch (H#10): a single-fd BAD_MATCH disabled DMABuf for\n  the whole process although the per-plane import that follows works.\n  It now only latches the single-EGLImage import off; the path is\n  disabled when per-plane (or a tiled single-fd import, which has no\n  per-plane fallback) also fails.\n- EGLImage cache (H#24): eviction called gst_mini_object_weak_unref() on\n  the render thread while a streaming thread could finalize the same\n  GstMemory. Eviction is keyed on a qdata destroy-notify that is never\n  removed, and the racy fenceExtProbe static (H#23) goes.\n- DMABuf->Vulkan (H#7, H#8): NV12/P010/I420 were imported as one\n  multi-planar VkImage that QRhi wrapped as a single-plane R8 texture\n  (invalid usage, no chroma), and the single-fd fourcc lookup meant\n  those were the only layouts ever imported. Only single-plane RGB\n  layouts are imported now, and validatePlaneHandles() rejects the rest\n  under a Vulkan QRhi so the factory demotes them to the CPU path. The\n  producer's write fences are waited for before import (Vulkan ignores\n  implicit fences) and a failed wait refuses the import; the image is\n  handed to QRhi as GENERAL so its first transition keeps the contents;\n  and the device function table is resolved per render thread and\n  VkDevice instead of once per process.\n- Imported VkImage/VkDeviceMemory are destroyed only once QRhi's queue\n  has drained (follow-up to H#1). Qt destroys a bundle when its pool\n  slot is reused, while the frame that last sampled it may still be\n  executing. The release callback submits an empty batch with a fence\n  and destroys the image once it signals; a QRhi cleanup callback waits\n  out the remaining entries while the device exists.\n\nTests: _testDmaBufEglBadMatchLatch and\n_testDmaBufVulkanImportRejectsMultiPlanar; the Vulkan release test\nfollows the new release callback.\n\nFixes review H#7, H#8, H#9, H#10, H#24.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(HwBuffers): correct GL, D3D, IOSurface and CUDA sync and lifetimes\n\n- GL display (H#4): before GStreamer 1.26 the EGL display derived from a\n  GstGLDisplayWayland can't be marked foreign, and its finalize\n  eglTerminate()s Qt's EGLDisplay (gstgldisplay_egl.c, 1.20-1.24). The\n  Wayland wrap is taken only on 1.26+; older versions wrap Qt's display\n  with gst_gl_display_egl_new_with_egl_display(), which marks it\n  foreign, as Qt's own GStreamer backend does.\n- GL sync (H#11): gst_gl_sync_meta_wait() waited in gst-gl's context and\n  left Qt's unordered. A fresh sync point is still set after the\n  GST_MAP_GL map (glupload uploads lazily on it), then the shared GLsync\n  is waited on server-side in Qt's context, with a CPU wait when Qt's\n  context has no sync objects. AHB CPU-waits a GstGLSyncMeta when one is\n  present, and its comment no longer claims an acquire fence.\n- Caches (H#23): the GL ring cache is thread_local for pop-out render\n  threads, and AHB entries are purged from a QRhi cleanup callback, so a\n  QRhi recreated at the same address can't hit them.\n- D3D device guard (H#5): the guards compared GstD3D1xDevice wrappers,\n  which every bridge prime recreates, so once a second stream re-primed\n  the bridge every frame of the first one was rejected. They compare the\n  wrapped ID3D11Device and use gst_d3d12_device_is_equal() (1.26+).\n- D3D12 staging (H#6): one slot per (size, format, plane) was shared by\n  every stream and queue, so two streams recorded the same command list\n  concurrently and frame N+1's copy overwrote what QRhi could still be\n  sampling. Each key now has a ring of slots with their own allocator\n  and list, leased until both the buffer and the frame bundle release\n  them; exhaustion demotes the frame to the CPU.\n- IOSurface (H#3): the GstCoreVideoMeta mirror carried a bogus GstBuffer*\n  field, so pixbuf was read past the meta and CFRetain'ed. It uses the\n  upstream layout (the same in 1.20-1.28) and refuses a meta whose\n  registered size differs.\n- CUDA (H#13, H#14): probe gst_cuda_memory_export (1.24+), the symbol the\n  path calls, under a renamed cache variable; sync the CUDA memory\n  before export; and wrap the exported fd, which the CUDA memory owns\n  and closes, with GST_FD_MEMORY_FLAG_DONT_CLOSE while a parent-buffer\n  meta pins the CUDA buffer, instead of closing it twice.\n- GL, D3D and IOSurface textures are wrapped with\n  FallbackPolicy::Disable, like the preflight (H#12).\n\nD3D, Apple and CUDA code is not compiled on this host. The D3D12 ring\nwas compile- and behaviour-checked against stub D3D12 types, and the\nCUDA TU syntax-checked against gst-plugins-bad's stub cuda.h.\n\nFixes review H#3, H#4, H#5 (D3D part), H#6, H#11, H#13, H#14; the GL,\nAHB, D3D and IOSurface parts of H#12 and the GL/AHB part of H#23.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* refactor(HwBuffers): share the import cache and the mapTextures tail\n\n- GstHwImportCache becomes a flat, compile-time-sized std::array LRU, so\n  lookups and inserts never allocate (S#21). It gains pin()/unpin() by\n  entry id (pinned entries survive eviction and clear) and an optional\n  \"destroyable here\" predicate whose failures are parked for\n  drainDeferred() on the owning thread. AHB's hand-rolled LRU and\n  deferred list, DMABuf's EGLImage orphan list and reset flag, and the\n  D3D staging pools move onto it (H#20), and the three hash functors\n  go. The GL \"ring cache\" only bumped the reuse counter while still\n  building a new wrapper, so it is deleted and that counter now counts\n  real reuse only.\n- GstHwFrameTexturesBase gains wrapPlanes() (always\n  FallbackPolicy::Disable, so preflight and createFrom agree, H#12),\n  allPlanesValid() and finishMap<FT>(), the \"reuse -> preflight -> build\n  -> verify planes -> hand over the sample\" tail every backend repeated\n  (H#18). A bundle with an unwrapped plane now records MapFailed and\n  warns once per path on every path. DMABuf (which preflights before its\n  import work) and IOSurface (whose texture refs already exist) call it\n  with the preflight off. DMABuf and AHB run their preamble through\n  checkMapPreconditions, and GstEglHelpers shares bindRhiContext() and\n  renderDisplay() between them. A zero handle now leaves its plane\n  unwrapped on every backend.\n\nTests: direct GstHwImportCache tests (LRU order, replace, eraseIf,\npinning across eviction and clear, all-pinned rejection, deferred\ndestruction), and Null-QRhi tests for zero handles, bundle reuse and an\nincomplete bundle that records MapFailed and leaves the sample for Qt's\nCPU fallback.\n\nAHB, D3D and IOSurface are not compiled on Linux; they were\nsyntax-checked against stub NDK, gst-d3d (1.26.0 signatures) and\nCoreVideo/Metal headers.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* refactor(HwBuffers): split the DMABuf import, share Vulkan and D3D code\n\n- DMABuf (H#16): mapTextures() was ~450 lines with two gotos, and the\n  single-fd and per-plane paths each carried the image-cache and bind\n  validation blocks. It is now a short driver over\n  resolveRenderDisplay(), waitForProducer(), EglAttribList,\n  GstHw::planeLayout(), acquireImage()/releaseImage() (a cached image is\n  pinned for the bind, so a concurrent reset can't destroy it),\n  bindPlane(), eglImageBinder(), importSingleFd() and importPerPlane().\n  Logic, log text and the EGL_BAD_MATCH latch are unchanged; two\n  unreachable checks go.\n- Vulkan (H#7): vulkan/GstVulkanImport holds what the gst-vulkan and\n  DMABuf->Vulkan paths share: the per-thread, per-VkDevice DeviceFns\n  table, the fence-deferred OwnedImage release, and admitImport(), the\n  single \"no import without producer sync\" policy. A refused import\n  records VulkanNoSync and warns once. The DMABuf import keeps its\n  single-plane restriction, since multi-planar import and producer sync\n  on QRhi's queue need waits inside QRhi's own submissions. A\n  data-driven test covers the sync policy for both paths.\n- D3D (H#21): GstD3DVideoBufferCommon::resolvePlanes<Api>() owns the\n  per-plane loop D3D11 and D3D12 duplicated (memory check, device guard,\n  null resource, subresource copy, guard commit), and each backend\n  supplies a small resolver. D3D12's resolver waits for submitted copies\n  before its leases are released, preserving the old destruction order.\n\nD3D is not compiled on Linux; both TUs were syntax-checked with Q_OS_WIN\nforced against stub d3d11.h/d3d12.h and gst-d3d headers (1.26.0\nsignatures).\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* build(HwBuffers): table-driven GPU path probes with per-backend options\n\nHwBuffers/CMakeLists.txt open-coded each backend. The Vulkan block\nrepeated the D3D probe's cache scrub, find_library and absolute-path\nlink; find_package(OpenGL COMPONENTS EGL) ran three times;\nGST_USE_UNSTABLE_API was added once per path; the D3D common sources\nwere gated on the header-only probe; and the Vulkan try-compile ran\nbefore the cheap QT_FEATURE_vulkan check (H#22).\n\n- Probe.cmake: _qgc_probe_gst_lib(<name> HAS_VAR HEADER SYMBOL\n  [PC_MODULE] [LIBNAMES LIB_VAR] [INCLUDES]) replaces\n  _qgc_probe_gst_d3d_path. It does pkg-config (split Windows paths\n  recovered), a cached header/symbol probe, and an optional find_library\n  with stale-path scrub and absolute-path link. Without LIBNAMES, CUDA\n  keeps linking its pkg-config library names and dirs. Cache names are\n  unchanged (QGC_GST_HAS_*, GST_D3D*_LIB, QGC_GST_VULKAN*_LIB,\n  PC_GStreamer_*), so the cmake stream's SDK-change purge still applies,\n  and the stale \"clear the cache after changing the SDK\" comment is\n  replaced.\n- HwBuffers/CMakeLists.txt: one row per path, iterated by a single loop\n  through _qgc_add_gpu_path.\n  - Every path needs Qt private headers, so that check runs once\n    instead of in each block and in the any-GPU-path block.\n  - Each row's REQUIRES variables are checked before its probe, so\n    QT_FEATURE_vulkan is tested before the Vulkan try-compile.\n  - EGL is found once, and GST_USE_UNSTABLE_API is added once.\n  - The D3D common sources are gated on an enabled D3D path.\n  - Special cases kept: CUDA include discovery, the static Vulkan\n    loader, IOSurface SKIP_PRECOMPILE_HEADERS, and the GLUPLOAD/DMABUF\n    bin selection.\n  - The global QGC_GST_ANY_GPU_PATH property is gone.\n  - The whole file now passes cmake-format and cmake-lint.\n- H#15: every row gets a QGC_GST_ENABLE_<PATH> option, default ON so\n  all paths stay compiled and tested. Disabled rows log why. Configure\n  also reports compiled paths the sink can't reach at runtime: DMABuf\n  and AHardwareBuffer under the glupload bin, and CUDA and Vulkan\n  everywhere, because their caps are never advertised. Runtime\n  behaviour is unchanged. The GStreamer README documents the options.\n\nVerified on this host: per-TU compile definitions and include dirs in\ncompile_commands.json, the HwBuffers object list and QGroundControl's\nGStreamer/EGL/Vulkan link libraries are identical before and after.\nToggling QGC_GST_ENABLE_VULKAN/GLMEMORY drops the define and selects\nthe DMABUF bin as expected. ctest -L 'FindModule|CMake' passes.\nWindows, macOS, iOS and Android configure paths could not be run here.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* chore(HwBuffers): drop dead DMABuf parameters and correct stale comments\n\nH#25:\n- directGlImportAllowed() ignored its hasModifiersExt parameter. It now\n  takes only the modifier, and states why tiled is rejected even with\n  EGL_EXT_image_dma_buf_import_modifiers. The test hook and its test\n  follow. The test still asserts that LINEAR is allowed and tiled is\n  rejected; only the ignored argument is gone.\n- GstDmaDrmCaps: the comment claimed the share-context display is\n  EGL_NO_DISPLAY, but the code then called eglInitialize on whatever it\n  resolved, which is Qt's own display whenever Qt uses EGL. That\n  contradicted GstEglHelpers (\"must not eglInitialize Qt's display\").\n  It now initializes only the default display it obtains itself, treats\n  a failed eglInitialize as no display, and the comment says so.\n- Comments left stale by hwplat-1 and this phase are corrected: the\n  EGL_BAD_MATCH latch, the class doc (now also covers the Vulkan\n  import), the AHB reuse comment, and the per-frame texture comment,\n  which blamed green frames on texture reuse.\n\n(clearDmaImageCacheLocked(EGLDisplay) went away with the cache port,\nand onSourceMemoryFinalized has had a single parameter since hwplat-1.)\n\nH#26: the DMABuf EGLImage cache stays off by default. Its ABA hazard is\nhandled (fd + full layout key, eviction on GstMemory finalize), but no\ntest or CI host exercises the direct importer: the glupload bin\nbypasses it, and the offscreen test QPA has no GL QRhi with a dma-buf\nproducer. The code comment and the GStreamer README now say this, and\ndocument QGC_GST_DMABUF_CACHE=1.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(VideoManager): harden qgcqvideosink frame delivery and allocation\n\nFrame delivery (S#1, S#2, S#3, S#13, S#15):\n- The sink posted one queued GUI event per frame, so a stalled GUI\n  thread accumulated frames, each pinning a decoder buffer, and showed\n  them late. It now keeps one pending frame per sink with one invoke\n  queued at a time, so superseded frames release their buffers at once.\n  The slot is replaced when the bound QVideoSink changes and cleared on\n  FLUSH_START.\n- The PTS regression guard was reset only in set_caps, which GstBaseSink\n  skips for identical caps, so after a restart, flush or new segment\n  every frame was dropped until PTS passed the old maximum. It resets on\n  FLUSH_STOP, SEGMENT and STREAM_START and resyncs on DISCONT or a\n  backward jump over 1 s.\n- snapshot_sink() no longer builds a QPointer on the streaming thread,\n  counters move only once a frame reached a sink, a new stop() vmethod\n  resets negotiation state and drops any undelivered frame, the\n  controller clears a released QVideoSink's frame, and 120 consecutive\n  map failures post GST_ELEMENT_ERROR (STREAM, FAILED) naming the path\n  and format.\n\nAllocation (S#6, S#7, S#14):\n- The bin's QUERY_DOWNSTREAM probe answered ALLOCATION itself, so the\n  sink's propose_allocation never ran inside qgcvideosinkbin, and a\n  standalone sink never answered CONTEXT. The sink overrides query() for\n  CONTEXT and leaves ALLOCATION to GstBaseSink; the probe is removed.\n- The system-memory proposal used a plain GstBufferPool, which never\n  attaches GstVideoMeta, so avdec direct rendering fell back to copying.\n  It now proposes gst_video_buffer_pool_new().\n- The zero-copy CPU frame cap was process-global, computed from a mostly\n  unset snapshot and checked non-atomically. Each sink has a CAS counter\n  capped at CpuVideoFramePool::kMaxPinnedFrames = 4, from which the\n  proposal's min-buffers is derived.\n\nTests: a synchronous sink harness covers coalescing, flush/stop dropping\nan undelivered frame, PTS resync with identical caps, the map-failure\nelement error and the controller clearing its frame; others check the\nVIDEO_META pool and the per-sink pinned cap. Fixed qWait() calls in the\nsink tests became condition waits.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(HwBuffers): give GPU frames a CPU fallback, keep state on restart\n\n- GstHwVideoBuffer::map() always returned an empty mapping, so when\n  mapTextures() failed, Qt's createTexturesFromMemory() fallback failed\n  too: every GPU import failure was a black frame plus a \"Cannot map a\n  video frame\" warning per frame. map(ReadOnly) now maps the held\n  sample's buffer with gst_video_frame_map(); external-OES frames still\n  refuse. takeSample() moved the sample out, so a CPU mapping or a\n  second mapTextures() found none; it now hands out a new ref.\n- glMemoryConsumable() dereferenced QGCRhiCapture::cachedRhi(), a\n  render-thread QRhi that can be destroyed at any time, from the\n  streaming thread. It reads the atomic DeviceSnapshot::backend.\n- onPipelineRestart(), run once per receiver start, reset every bridge\n  and import cache, so starting a second stream tore down GPU objects\n  the first one was using (and left the rearm() calls after it dead). It\n  now only rearms exhausted prime-retry latches; full resets stay with\n  sceneGraphInvalidated, window swaps and device loss.\n\nTests: a buffer whose mapTextures() always fails still yields textures on\na Null QRhi with the original pixels, and a restart neither resets\nbridges nor clears import caches.\n\nFixes review S#5, S#8, S#9, H#2 (part a) and H#5 (restart part).\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* refactor(VideoManager): untangle qgcqvideosink from HwBuffers internals\n\n- GstHwTypes.h holds HwVideoBufferPath (with a _Count sentinel),\n  GstHw::kPathCount, GstHw::toString() and HwVideoBufferContext. EGL\n  displays are stored as void* and MappedFrame always carries gpuPath\n  and demoted, so no struct changes layout with the QGC_HAS_* defines\n  and the factory header no longer includes EGL. The duplicated path\n  counts and label tables use them, Qt-private headers leave\n  GstHwPathTelemetry.h and HwBuffers.h, and unused counters go.\n  (S#12, S#25 partial)\n- qgcqvideosink stored its construct-only gpu-zerocopy property but\n  never read it; a context pushed in from the GUI thread drove GPU\n  mapping. The sink's new start() vmethod builds the context from the\n  property, so gst_qgc_q_video_sink_set_hw_context() and\n  gst_qgc_video_sink_bin_get_gpu_zerocopy() go. The instance structs\n  move into the .cc files, the sink keeps its C++ state in the\n  instance, the bin drops four write-only fields, and BinChain moves to\n  GstQgcBinChain.h so its rollback is tested directly. (S#16, S#17)\n- The D3D11/D3D12 pool proposal moves into\n  HwBuffers::proposeDeviceBoundPool(), so gstqgc no longer includes\n  bridge internals. The glupload and forced-LINEAR DMA_DRM format lists\n  come from new offers flags in the format table and produce the same\n  lists. (S#19 partial, S#23)\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(VideoManager): show the first buffer after preroll only once\n\nGstVideoSink's default show-preroll-frame=TRUE runs show_frame for the\npreroll buffer and again when that same buffer is rendered. In\nqgcqvideosink that mapped the first buffer after every preroll twice\n(two GPU imports or CPU copies) and counted it twice in frames-input and\nframes-delivered. QGC drives its pipelines straight to PLAYING, where\nrender follows preroll at once, so the preroll frame adds nothing for a\nlive display. The sink now turns show-preroll-frame off in constructed()\n(it is a construct property, so instance_init is too early).\n\nThe test harness no longer has to disable it itself, so every sink test\nnow runs with the element's default.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* feat(VideoManager): report frame stats per qgcqvideosink\n\nThe GstHwPathTelemetry counters are process-wide and reset on read, but the\nreceiver logs them per stream, so with two receivers one teardown log\nincludes the other's frames and resets its counters. qgcqvideosink now\nkeeps its own GstHwPathTelemetry::SinkCounters (frames delivered per path,\nGPU fallbacks, stream demotions) and exposes them, with frames-input,\n-dropped and -delivered, through a read-only \"stats\" property\n(qgc-video-sink-stats GstStructure of guint64 fields; per-path field names\ncome from GstHwPathTelemetry::sinkFramesField()).\nHwBuffers::formatSinkStats() turns that structure into the same PathStats\nthe receiver logs today, so it can switch from formatPathStats(); the\nglobal counters, formatPathStats() and takeExtraPathStats() are unchanged.\n\nThe once-per-caps-epoch demotion latch moves from the factory's\nHwResolvedPathCache into the sink. takeExtraPathStats() now also reports\nthe image-cache hit/miss counters the DMABuf, AHardwareBuffer and D3D12\nimports record.\n\nReview S#10, S#4 (latch).\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* perf(VideoManager): skip GPU path selection for frames no path imports\n\nWith gpu-zerocopy on, every system-memory frame (software decoders hit\nthe bin's video/x-raw catch-all) built a GstSample and ran the whole\ngst_is_*_memory ladder, then a global mutex/QSet lookup, an\nUnknownMemType fallback record and a demotion, only to end up on the CPU.\n\n- set_caps records whether the caps carry a memory feature other than\n  system memory, and show_frame does not attempt a GPU path otherwise.\n- HwResolvedPathCache remembers, per caps epoch, an allocator type no\n  compiled path imports, so later frames from it go straight to the CPU;\n  the mutex/QSet debug latch goes away.\n- A new makeHwVideoBuffer(GstBuffer*, GstCaps*, ...) overload creates the\n  GstSample only once a path has matched; the GstSample overload stays\n  for existing callers.\n- Plane-handle validation failures warn once per caps epoch instead of\n  every 64 frames process-wide: some imports (multi-planar DMABuf under a\n  Vulkan QRhi) fail on every frame of a stream.\n- The stale Jetson remark in the CUDA comment is dropped.\n\nA data-driven test drives a standalone sink with system-memory buffers and\nchecks, through the sink's stats and the global no-path counter, that GPU\nselection is skipped for system-memory caps or gpu-zerocopy=FALSE and runs\nonce per epoch for GPU caps.\n\nReview S#4.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(HwBuffers): size CPU planes by component, forget dead QRhi verdicts\n\n- CpuVideoFramePool and GstHwVideoBuffer::map() passed plane indices to\n  the GST_VIDEO_*_COMP_* macros, which take component indices: right for\n  today's format table, wrong once a plane's first component isn't the\n  plane's index (AV12's alpha plane would be sized as the half-height\n  V). Planes are sized through gst_video_format_info_component() (1.18+)\n  and both map() implementations share CpuVideoFramePool::mapDataFor().\n- The import preflight memo was keyed on the QRhi* address and outlived\n  the QRhi, so a new QRhi at a recycled address could reuse a stale\n  verdict. A keyed QRhi cleanup callback drops the dying QRhi's\n  verdicts.\n- hwBufferEnvConfig() parsing moves into readHwBufferEnvConfig() so the\n  toggle syntax is testable.\n\nTests: plane heights for NV12/YV12/AV12, an odd-sized (5x3) CPU copy, env\ntoggle parsing and verdicts dropped with their QRhi. Two more\nqgcqvideosink tests on the sink harness cover caps renegotiation inside\none stream (the next frame carries the new format and size) and a\nGstVideoCropMeta reaching the delivered frame's viewport through\nshow_frame; the harness gains makeFrame()/pushBuffer().\n\nFixes review S#20, S#24 and S#27 (partial).\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* refactor(VideoManager): rename gstqgcelement.cc to gstqgcelements.cc\n\nThe translation unit that defines the plugin's debug category and\nqgc_element_init() now matches its header, gstqgcelements.h, and the name\nthe GStreamer.cc link-stripping hint already uses. Pure git mv plus the\nCMake source list.\n\nGStreamerFrameMap.{h,cc} keep their name for now: the hwplat-owned\ndmabuf/gl/vulkan tests and the GStreamer CMakeLists comment reference it.\n\nReview S#26 (partial).\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* refactor(HwBuffers): derive the GPU context bridges from one base class\n\nGL and Vulkan each repeated a file-static mutex, object set, prime-retry\nlatch, the five vtable thunks and handle/answer/reset/rearm; the D3D side\nwent BridgeOps -> D3DUser -> BridgeVTable and rebuilt the vtable and a\nstack context-type array on every message.\n\nGstContextBridgeBase now owns the mutex, the retry latch (folded in from\nGstBridgePrimeRetry.h) and NEED_CONTEXT / GST_QUERY_CONTEXT handling,\nprime(), reset() and rearm(). Bridges override primeLocked(),\nrefObject(), buildContext() and clearLocked() (plus logHandoff()); the\nD3D11/D3D12 bridges share GstD3DContextBridge (backend gate, device,\nfirst-handoff log, refDevice) and only build their device and context.\nEach bridge is a constinit object reached through instance(), so the\nstatic registrars and facade call sites use that instead of per-bridge\nfree functions.\n\nBehaviour is unchanged: the same prime/retry/latch transitions per\nbridge (GL/Vulkan bounded retries for a missing native handle, D3D\nretries until QRhi runs its backend), the mutex is still released\nbefore gst_element_set_context()/gst_query_set_context(), and D3D's\nfirst hand-off still logs once. rearm() is now a no-op member on the\nD3D bridges, as it always was in effect.\n\nFixes review H#17.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(HwBuffers): build the AHardwareBuffer format without setPixelFormat\n\nThe factory's AHardwareBuffer branches called QVideoFrameFormat::setPixelFormat(),\nwhich Qt 6 does not have, so any build with the AHardwareBuffer path (gst >= 1.28\non Android) failed to compile. No CI configuration compiles that path today.\n\nRebuild the format around Format_SamplerExternalOES instead, carrying over every\nother property (viewport, scan-line direction, frame rate, color space, transfer\nand range, mirroring, rotation, max luminance).\n\nVerified with an -fsyntax-only compile of the factory against stub\nandroid/hardware_buffer.h and gst/android/gstandroid.h headers.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* refactor(HwBuffers): register each GPU path once and drop stale names\n\n- Adding a backend meant editing about ten #ifdef sites (factory\n  selection, kEnabledPaths, the context-query, restart and\n  pool-proposal ladders, EGL-display setup, and GstContextBridgeRegistry\n  arrays fed by static registrars while initializeOnce() was empty).\n  Each backend TU now defines one HwPathDescriptor (matches, admits,\n  construct, onImportFailed, prepareContext, resetCaches, proposePool,\n  bridge). GstHwPathRegistry holds them in selection order,\n  HwBuffers::initializeOnce() registers them from the qgc plugin_init,\n  and the factory, bus handler, context queries, restarts, resets, pool\n  proposals and stats loop over it. The registry and registrars are\n  gone. Selection order is unchanged (CUDA, DMABuf, GLMemory, D3D11,\n  D3D12, Vulkan, IOSurface, AHardwareBuffer), and the per-epoch fast\n  path now serves CUDA too. (S#11, S#18, H#19, S#19 pool proposals)\n- GstHwVideoBuffer::storageTag() and its seven overrides had no callers.\n  takeSample() returns a new ref since the CPU-fallback fix, so it is\n  now refSample(). dmaDrmAwareVideoInfo() is platform-neutral caps\n  parsing, so it moves to common/GstHwVideoInfo and gstqgc no longer\n  includes a DMABuf header. (S#25, S#19 remainder)\n- The DMABuf barrier telemetry is named after poll(), which replaced the\n  mmap barrier: recordCpuBarrierWait, recordProducerFenceTimeout and the\n  DMABuf-cpu-barriers stats label. QGC_GST_DMABUF_NO_MMAP_FENCE keeps its\n  user-facing name.\n\nTests: the registry tests drive real GstContextBridgeBase subclasses\nthrough the facade, and _testHwPathRegistrySelection covers first-match\norder, vetoes, failed imports and the fast path.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* test(VideoManager): give every GStreamerTest slot a non-streaming stub\n\nGStreamerTest.cc's QGC_GST_SKIP_TEST list is what defines the test slots when\nQGC_GST_STREAMING is off, and moc references every declared slot, so a missing\nentry breaks the link of a build without GStreamer. Sixteen slots had none:\nhwplat-1's frame-texture, Vulkan-owned-texture, EGL_BAD_MATCH-latch and\nmulti-planar-Vulkan tests, the D3D11/D3D12 dispatch and QRhi tests, and three\nolder ones (_testHwFrameTexturesRejectsForeignOldTextures,\n_testQgcVideoSinkBinAllocationQueryAdvertisesVideoMeta,\n_testSourceFactoryUdp265UsesExplicitDepayAndParser).\n\nChecked by preprocessing every GStreamer test TU without QGC_GST_STREAMING\n(every declared slot now has exactly one definition) and by an -fsyntax-only\ncompile of GStreamerTest.cc in that configuration.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(HwBuffers): fix GPU path selection, CUDA includes and CPU fallback\n\nEach fixes a regression from an earlier commit of this series: the\nsystem-memory fast path, the table-driven probes and the CPU fallback.\n\n- Path selection was skipped whenever the caps carried no memory:*\n  feature, but vtdec hands out IOSurface-backed memory and V4L2 decoders\n  export dmabuf under plain video/x-raw, so the IOSurface path never ran\n  on iOS and direct DMABuf import never ran for V4L2. The sink now\n  decides on the memory: only frames without a GPU caps feature whose\n  first memory comes from the system allocator skip selection, so\n  software-decoded frames keep the fast path. A memfd-backed row in\n  _testQgcQVideoSinkGpuPathSelection fails with the old gate.\n- The CUDA probe used its INCLUDES only for the header try-compile, so\n  with a CUDA toolkit or the stub headers configure enabled the path and\n  GstCudaVideoBuffer.cc failed on \"cuda.h: No such file or directory\".\n  <name>_INCLUDE_DIRS now carries INCLUDES; only the CUDA row passes\n  any. With upstream's 1.24.2 stub cuda.h the file failed before and\n  builds after (GStreamerTest passes with CUDA registered); the default\n  configuration's compile_commands.json and CMakeCache.txt are\n  byte-identical.\n- On eglfs, DMABuf YUYV/UYVY frames advertise RGBA8888 so the EGLImage\n  import picks Qt's RGB shader, but the CPU-fallback map() still mapped\n  the 2-byte-per-pixel memory and Qt uploaded it as w x h RGBA: wrong\n  pixels and a read about 2*w bytes past the frame. GstHwVideoBuffer\n  records the format it was constructed with, and map() refuses when\n  format() advertises another.\n  _testHwVideoBufferCpuMapRefusesForeignLayout fails without the fix.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* test(gstreamer): check failure diagnostics, add a fake-SDK fixture\n\n- The five WILL_FAIL FindModule script tests passed on any error, a typo\n  or a missing include included. They now run through\n  run_expected_failure_test.cmake with an EXPECTED_REGEX, sharing one\n  helper with the argument-validation cases. test_json's tautological\n  length assertion is fixed, the misnamed test_orchestrator_idempotent\n  folds into test_components, and the scripts' cmake_minimum_required\n  matches the project's 3.25. (C#21)\n- The Orchestrator and target creation had no coverage. A configure-mode\n  fixture (tests/fixtures/FakeSdk, driven by test_orchestrator.cmake)\n  generates a Linux-layout fake SDK and configures the real Orchestrator\n  against it: one scenario asserts the GStreamer::* targets, the Layout\n  properties, the version and the probe results; another requires an\n  unchanged reconfigure to keep that state without re-running\n  pkg-config. Script tests cover the Android ABI mapping and the Windows\n  SDK root selection. The fixture tests run on Linux hosts only. (Part\n  of C#20)\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(gstreamer): correct SDK checksums, root caching and module checks\n\n- Checksums: the .sha256sum sidecar regex used \"{64}\", which CMake\n  regexes don't support, so every sidecar was reported unparseable, an\n  unpinned SDK could never use one, and each configure re-fetched it\n  with a warning. The 64-digit class is spelled out. A pinned checksum\n  is authoritative, so pinned SDKs no longer fetch the sidecar at all\n  (3 x 30 s offline before), and hex digests are compared lowercase\n  everywhere. (Part of C#20, C#27)\n- Root: the Orchestrator FORCE-cached the discovered root into\n  GStreamer_ROOT_DIR, so reconfigures treated it as user input: version\n  bumps never re-downloaded, a vanished Android cache hit a layout\n  FATAL, iOS switched SDKs and GStreamer_AUTO_DOWNLOADED flipped to\n  FALSE. GStreamer_ROOT_DIR is now user-only, and discovery records its\n  choice in INTERNAL QGC_GST_RESOLVED_{ROOT,VERSION,AUTO}. An SDK\n  fingerprint purges the pkg-config, find_* and probe caches when the\n  SDK changes; the summary, verify_executable.py and the Windows\n  workflow read the resolved root; and iOS accepts framework, slice and\n  Versions/<v> roots. (C#1, C#2, C#15)\n- Modules: mandatory modules were reported FOUND unconditionally, so a\n  missing -dev package configured and failed later at #include.\n  Configure now fails naming the missing pkg-config modules. Gl and\n  GlPrototypes become optional components: only gst-gl-gated code uses\n  them, and the aarch64 sysroot ships no .pc files for their\n  dependencies. (C#5)\n\nTests: offline checksum-authority cases (an agreeing pin wins, a\ndisagreeing cached sidecar is ignored for a pinned SDK, an unpinned\nsidecar is accepted only with GStreamer_REQUIRE_CHECKSUM OFF); fake-SDK\nreconfigures after a root switch, an in-place upgrade and with a\nreusable download; script tests for root selection, cache invalidation,\nthe .pc version reader and the iOS bundle mapping; and missing-mandatory\nand missing-gl fixture scenarios.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(gstreamer): lock and stamp SDK acquisition, extract one Android ABI\n\n- The SDK cache under CPM_SOURCE_CACHE is shared by build directories\n  and CI jobs, yet each platform downloaded through a fixed\n  <archive>.tmp and extracted in place, so concurrent configures could\n  truncate each other's download or delete a tree in use, and\n  completeness was judged four different ways. qgc_gst_acquire_sdk now\n  holds a file(LOCK) around download and extraction, extracts into\n  <content>.partial, renames it into place only once complete and stamps\n  it with the archive hashes; a mismatch re-extracts. Trees left by the\n  old layout are ignored, and qgc_resilient_download uses a per-process\n  temporary name. (C#7)\n- Android unpacked the universal SDK through CPMAddPackage, extracting\n  all four ABIs (about 1 GB) per build directory, writing a\n  gstreamer-config.cmake redirect that shadowed find_package(GStreamer)\n  and building an ill-formed file:// URL on Windows hosts. It goes\n  through qgc_gst_acquire_sdk and extracts only \"<abi_dir>/*\", so each\n  ABI build, Qt multi-ABI sub-builds included, gets its own stamped\n  tree. (C#8)\n\nTests: test_sdk_acquire drives the helper offline with a pinned archive\n(reuse, re-extraction after a foreign or missing stamp, an interrupted\nextraction or a re-pin, and the lock held while extracting), and\ntest_android_sdk_extract checks the per-ABI roots.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(gstreamer): replace FindGStreamer, keep pkg-config state scoped\n\n- FindGStreamer.cmake was not a real find module: it read the\n  Orchestrator's globals, needed Link.cmake and the pkg-config\n  environment set up by its caller, had dead COMPONENTS paths, and\n  probed every plugin with a non-QUIET pkg_check_modules even for shared\n  layouts (~26 failing probes printed per Linux configure). Its logic is\n  now qgc_gst_create_pkgconfig_targets() in Targets.cmake, which probes\n  plugin targets quietly and only for static layouts. Targets, versions\n  and *_FOUND results keep their contents, and cmake/find-modules leaves\n  CMAKE_MODULE_PATH. The derived code keeps L. E. Segovia's SPDX LGPL\n  notice, now credited to GStreamer's own FindGStreamer.cmake. (C#9,\n  completes C#8)\n- Discovery leaked pkg-config state into everything configured after\n  it: a FORCE-cached PKG_CONFIG_ARGN mixing user and derived flags\n  (hence Windows' per-configure FILTER), a FORCE-cached\n  PKG_CONFIG_EXECUTABLE, the SDK's PKG_CONFIG_LIBDIR/PATH in the\n  environment and the SDK on CMAKE_PREFIX_PATH. Derived flags and the\n  SDK's pkg-config are now normal variables of the GStreamer directory,\n  the environment is restored once HwBuffers and gstqgc are configured,\n  and the SDK paths are added only inside target creation. Flags older\n  build directories cached are stripped once. (C#13)\n\nThis host's compile flags, link line and GStreamer cache entries are\nunchanged. The fake-SDK fixture gains a static-targets scenario, checks\nthat shared layouts probe no plugin (fails on the old module), that the\ncache keeps only user flags and that the environment is restored, and\ncovers the legacy-flags migration.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(gstreamer): match the Windows SDK to the target, install it portably\n\n- An auto-downloaded Windows SDK chose arm64 only from\n  CMAKE_GENERATOR_PLATFORM or CMAKE_SYSTEM_PROCESSOR, so a Ninja + MSVC\n  cross build from a vcvarsamd64_arm64 prompt got the x64 SDK.\n  _qgc_gst_windows_sdk_arch prefers CMAKE_CXX_COMPILER_ARCHITECTURE_ID\n  and falls back to the old logic; a data-driven case table in\n  test_windows_sdk_root covers it. (C#14)\n- The installer now runs into install.partial, which is renamed once\n  complete, but cerbero's Inno Setup script records its install dir in\n  the GSTREAMER_1_0_ROOT_MSVC_<arch> variable (only when unset, so it\n  stuck even across a later official install), in the registry and in\n  an Add/Remove Programs entry, all naming the dead .partial path.\n  /portable=1 skips all of these, and /CURRENTUSER drops the elevation\n  request (1.28.4+). test_windows_sdk_root's stand-in installer fails\n  without it.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* docs(gstreamer): add the LGPL notice for code derived from cerbero\n\nThe Android mobile target (_qgc_create_android_mobile_target and its\nhelpers) and the iOS GStreamerMobile framework target are derived from\ncerbero's data/mobile/FindGStreamerMobile.cmake. The derivation shows in:\n- the legacy GSTREAMER_* alias handling;\n- the fonts/ca_certificates components and their cache variables;\n- the plugin Java collection and the copy targets;\n- the framework properties (org.gstreamer.GStreamerMobile).\n\nThe GStreamer Android SDK installs that file as\nshare/cmake/FindGStreamerMobile.cmake (recipes/gst-android-1.0.recipe).\nIt carries \"SPDX-FileCopyrightText: 2024 L. E. Segovia\" and is licensed\nLGPL-2.1-or-later. Upstream writes the license tag as\nSPDX-License-Ref; these files use the standard SPDX-License-Identifier\ntag.\n\nBoth files now carry that notice, the same way Targets.cmake does for\nFindGStreamer.cmake. Each also has a provenance note naming the derived\nparts and the QGC changes.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* refactor(gstreamer): share plugin policy and static-init generation\n\n- \"A plugin is available when present or when one of its alternate sets\n  is\" was implemented four times: the Orchestrator's FOUND loop,\n  Android's runtime-required backstop, the install verifier's generated\n  EXISTS chains and gstreamer_filter_alternates. PluginPolicy.cmake's\n  gstreamer_plugin_satisfied() and gstreamer_missing_required() serve\n  all of them; the verifier includes PluginPolicy.cmake at install time\n  and checks under $ENV{DESTDIR}${CMAKE_INSTALL_PREFIX}. A new FakeSdk\n  install scenario covers alternates and a missing plugin. (C#10)\n- gst_init_static_plugins() came from two generators and three\n  configure_file() calls, with template variables leaking into the\n  consumer scope. qgc_gst_generate_static_init(TARGET PLUGINS\n  GIO_MODULES) in StaticInit.cmake configures the template next to it,\n  adds the result to the target and skips its PCH; Android,\n  desktop-static and iOS (with G_IO_MODULES) call it. Desktop-static\n  registration lists only plugins with a GStreamer::<plugin> target, so\n  alternate-satisfied names no longer get an unresolvable register call.\n  The unsupported function-scope enable_language(OBJC OBJCXX) and a\n  wrong consumer comment go. test_static_init checks the generated\n  source and compiles it against the host headers. (C#11, part of C#12)\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(gstreamer): fix static plugin registration and linking on mobile\n\n- iOS registered every plugin descriptor nm found in the merged archive,\n  so every iOS build linked all of the SDK's plugins, GPL encoders such\n  as x264 included, while the allowlist only created empty alias\n  targets. iOS now registers the requested plugins the archive contains\n  (plus the Debug MockLink encoders, as on Android), with alias targets\n  for those only. One Orchestrator check covers every static layout: a\n  requested plugin missing from the SDK warns (alternate-aware), and a\n  missing runtime-required plugin fails configure on Android and iOS.\n  (C#3)\n- Android whole-archived plugins with --whole-archive link options,\n  which CMake emits before the objects and de-duplicates, while the same\n  archives were linked again by path and wrapped in a link group that\n  grouped nothing. Each plugin archive is now a STATIC IMPORTED\n  GStreamer::<plugin>_archive linked through\n  $<LINK_LIBRARY:WHOLE_ARCHIVE,...>, so it appears exactly once. HIDE on\n  ELF links the library and adds --exclude-libs instead of passing only\n  the flag. (C#4, C#23)\n\nTests: test_ios_static_plugins covers the iOS selection, and a new\nandroid-mobile fixture scenario reads the generated link line (each\narchive once inside --whole-archive, no group, the core with\n--exclude-libs) and fails a fake SDK without udp; it fails against the\nold code.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(gstreamer): fix macOS install prefixes and Android file staging\n\n- The macOS framework and flat-SDK installers baked the configure-time\n  ${CMAKE_INSTALL_PREFIX} into DESTINATIONs and install(CODE), so\n  `cmake --install --prefix` or DESTDIR staging put GStreamer apart from\n  the bundle, touched paths outside DESTDIR and then failed the\n  framework check. DESTINATIONs are relative, install(CODE) builds paths\n  from $ENV{DESTDIR}${CMAKE_INSTALL_PREFIX}, framework links use\n  file(CREATE_LINK ... SYMBOLIC), and the app's GStreamer.framework\n  rpath fixup is DESTDIR-aware too. (C#6)\n- The Android mobile target copied plugin Java sources, fonts and the\n  CA bundle into the source tree's android/, which needed .gitignore\n  entries, broke read-only trees and raced between ABIs and build\n  directories. They are staged in the build directory instead\n  (QGC_ANDROID_EXTRA_JAVA_SOURCES_DIR and a new extra_assets directory\n  that build.gradle adds), with one copy rule per file feeding a\n  gstreamer_android_files_<abi> target. Copies earlier builds left in\n  the package sources are deleted and reported. (C#16)\n\nTests: an install-macos fixture scenario runs both installers with\n--prefix and DESTDIR, and the android-mobile scenario checks the staged\nfiles, the stale-copy removal and the app dependency; both fail against\nthe old code.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* refactor(gstreamer): drop dead outputs and macros, one platform table\n\n- Dead outputs and checks go: GSTREAMER_EXTRA_DEPS\n  (gstreamer_build_apis_and_deps becomes gstreamer_build_apis),\n  QGC_GSTREAMER_PATCH_*, GStreamer_Mobile_MODULE_NAME, the\n  QGCGStreamer_*_FOUND and iOS FOUND outputs, Android's GLOBAL-property\n  guard and always-TRUE NEEDS_BSYMBOLIC_FIX, and a required-variables\n  check the existence checks already cover. (Part of C#22)\n- Platform.cmake: qgc_gst_platform() and one descriptor row per platform\n  (version variable, plugin key, discovery command, installer) replace\n  the Orchestrator's and Install.cmake's if-chains, dispatched through\n  cmake_language(CALL). Installers report the plugin directory they\n  used and the install verifier checks it, so the two can't drift; an\n  unsupported platform fails at the lookup. (Part of C#18)\n- The 250-line Android mobile-target macro, the five discovery macros,\n  _qgc_create_pkgconfig_targets and _qgc_detect_dmabuf leaked scratch\n  state into the consumer, HwBuffers and gstqgc. They are functions that\n  return only their documented outputs; unreachable leftovers from\n  cerbero's FindGStreamerMobile.cmake go, and _qgc_detect_dmabuf reuses\n  the quiet header probe. (Part of C#19, C#22, C#25)\n\nLinux status lines, compile flags, link line and cache are unchanged,\nevery FakeSdk scenario produces identical state and build rules, and the\n375-file Linux install is unchanged.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(gstreamer): normalize SDK roots as single paths and name probes once\n\nTwo fixes:\n\n- C#24: Layout.cmake and the macOS framework lookup normalized a\n  single root with cmake_path(CONVERT ... TO_CMAKE_PATH_LIST). On POSIX\n  hosts that splits the path at ':'. They now use\n  cmake_path(SET ... NORMALIZE), which also converts native separators.\n  test_layout gains a root containing ':'. Without the fix it fails\n  with \"SDK not found\".\n- C#25: the GstVideoOrientationMeta probe was cached under\n  QGC_GST_HAS_VIDEO_ORIENTATION_META_<target>. try_compile passes that\n  name to the compiler as -D<var>, and with '::' in it the probe could\n  silently turn FALSE under -Werror. It also probed GStreamerMobile,\n  which on iOS is a framework this project builds; try_compile only\n  links imported targets.\n\nThe orientation probe now runs once, against the core target, as\nQGC_GST_HAS_VIDEO_ORIENTATION_META. Its result is applied to both the\ncore and GStreamerMobile, which carries the same headers. On this host\nthe result is unchanged: no define, since the system has 1.24.2. The\nFakeSdk reconfigure scenarios still flip it when the headers appear.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* build(gstreamer): declare the GStreamer configure knobs\n\nSeveral GStreamer knobs were read without ever being declared, or were\nborrowed from find_package. Each now has a declaration and a docstring.\n\n- QGC_GST_VERSION (cache STRING, empty by default) overrides the\n  platform's gstreamer.version from build-config.json. Previously the\n  override was GStreamer_FIND_VERSION, a name find_package reserves.\n  The resolved request is now the internal QGC_GST_REQUESTED_VERSION.\n  Nothing in .github/ or tools/ passed the old name, so no deprecation\n  path is kept. The new version-override FakeSdk scenario checks that\n  the override reaches the pkg-config version check.\n- GStreamer_USE_STATIC_LIBS and GStreamer_USE_FRAMEWORK are now\n  option()s with their platform defaults. Discovery still overrides\n  them per SDK with normal variables. GStreamer_USE_XCFRAMEWORK is\n  set only by iOS discovery and is no longer a pseudo-option.\n- QGC_GST_ALLOW_UNVERIFIED_CA, the iOS CA-bundle escape hatch, is an\n  option.\n- The legacy GSTREAMER_ROOT and GStreamer_ROOT spellings still work,\n  but now print a deprecation message pointing at GStreamer_ROOT_DIR.\n- The QGC_GSTREAMER_TEST_WIN32 hook is gone from Install.cmake. The\n  Windows guard test sets WIN32 itself.\n\ntest_sdk_state now checks that an SDK change keeps user options which\nshare the GStreamer prefixes: QGC_GST_ENABLE_* (HwBuffers),\nQGC_GST_VERSION, GStreamer_USE_*, and the others. A purge regex that\nmatched QGC_GST_ENABLE_ makes it fail.\n\nOn Linux the only configure difference is the new cache entries.\n\nPart of review C#28.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* refactor(gstreamer): prefix internal helpers and document the modules\n\n- Private helpers that mixed the _gstreamer_ and bare _qgc_ prefixes\n  take _qgc_gst_; the pkg-config and iOS target factories become\n  _qgc_gst_create_sdk_targets and _qgc_gst_create_ios_targets. Link.cmake\n  keeps its _gst_* names, which Probe.cmake calls. The iOS XCFRAMEWORK\n  layout mode, which also covers GStreamer.framework bundles, becomes\n  MERGED_STATIC, and QGCGStreamer_FIND_COMPONENTS becomes\n  QGC_GST_COMPONENTS. Behaviour, status lines and FakeSdk state are\n  unchanged. (Part of C#29)\n- The GStreamer README's \"Build Configuration\" covers build-config.json,\n  the configure options, GStreamer_ROOT_DIR versus\n  QGC_GST_RESOLVED_ROOT, the per-platform allowlist behaviour and every\n  module. Orchestrator.cmake gets an Input/Sets header, the Helpers.cmake\n  index names every function, and cmake/README.md gains a GStreamer\n  section with the QGC_GST_ENABLE_<PATH> options. (Part of C#28)\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(VideoReceiver): make teardown safe and recordings crash-safe\n\nTeardown:\n- stop() returned early when the URI was empty, so clearing the URI and\n  then stopping (source \"Disabled\", app exit) left the pipeline and its\n  probes running against the receiver. Teardown is gated on the\n  pipeline and reports STATUS_INVALID_STATE when nothing ran. (R#1)\n- A failed start() kept dangling element pointers, probe ids and\n  _streaming == true for the next stop(); one _resetPipelineState() now\n  serves both paths. (R#2)\n- The destructor waited 2 s for a worker that can spend 3 s finalizing a\n  recording, so QThread could be destroyed while running (qFatal).\n  Teardown is synchronous with a deadline above the EOS budget. (R#3)\n- createVideoSink() returns a sunk ref and the receiver no longer adds\n  one, so each restart stops leaking a sink. (R#7)\n- The source EOS probe lives with the pipeline, so stopDecoding() keeps\n  EOS detection and a sinkless stop no longer leaks the pad. (R#8)\n- Cross-thread flags are atomic and published in order, an ERROR\n  triggers one reconnect per pipeline, the watchdog uses a monotonic\n  clock with a 1 s floor, the probes drop Q_ASSERT, and the keyframe\n  probe offsets by running time and clears its own id (every recording\n  stop removed an already-gone probe, with a GLib warning). (R#9 and\n  R#10 partial, R#11, R#17)\n\nRecording:\n- qtmux ignores reserved-moov-update-period unless reserved-max-duration\n  is set, so faststart won: the whole mdat was spooled to /tmp and the\n  file appeared only at EOS, a kill left nothing playable and long\n  recordings could fill a tmpfs. faststart goes; reserved-max-duration\n  (2 h, ~8 MB) and a 5 s moov update period make MP4/MOV robust. (R#5)\n- The finalize wait could pop a stale fragment-closed or an ignored\n  ERROR and truncate the current file. Queued messages are drained\n  before EOS and only the current file sink's messages count. (R#6,\n  minimal)\n\nThe new GstVideoReceiverTest streams live x264 RTP over loopback and\nchecks start/decode/stop/destroy, stop after clearing the URI, a failed\nstart on a bound port, one sink ref across restarts, a playable\nmid-recording copy, destruction while recording, and two consecutive\ncomplete recordings. Each test failed with its fix reverted.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(VideoReceiver): drain the bus and link pads on a QThread worker\n\n- GstVideoReceiver runs on a QThread with a real event loop and a\n  context QObject living on it, replacing the hand-rolled task loop. The\n  watchdog and reconnect timers run on the worker, the backoff counter\n  is worker-confined, and start() snapshots its configuration into a\n  StartConfig, so worker and streaming threads no longer read members\n  the GUI thread writes. GStreamer-only state moves from VideoReceiver\n  into GstVideoReceiver. (Part of R#9)\n- The bus was never drained: the HwBuffers sync handler passed every\n  message but NEED_CONTEXT, so STATE_CHANGED, QOS, LATENCY and ERROR\n  queued for the pipeline's life. One sync handler routes each type to\n  cheap posting-thread work or a worker task tagged with the pipeline\n  generation, and drops every message. Recording completion settles a\n  per-recording RecordingFinalizer instead of popping the bus, and\n  onStopRecordingComplete always fires. A recorder ERROR (disk full,\n  unwritable path) now ends only the recording, not the stream.\n  stopDecoding() tears the branch down synchronously instead of waiting\n  for a branch EOS that could leave _removingDecoder stuck. (R#6, R#12)\n- pad-added ran on streaming threads and changed receiver state and the\n  pipeline while the worker ran startDecoding()/stop() on the same data,\n  so video could stay black or a second decoder leak in. pad-added now\n  blocks the pad and queues the link on the worker under the pipeline\n  generation, so every pipeline mutation happens there. (R#4, part of\n  R#9 and R#18)\n\nTests: stopDecoding before the first frame, stop() during a\nstopRecording(), a recorder error that keeps the stream, an empty bus\nafter streaming, and decoding requested before any data arrives.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(VideoManager): make the receiver the only one that reconnects\n\nTwo mechanisms restarted a failed stream. On a watchdog timeout, a\npipeline error or end of stream, GstVideoReceiver stopped itself,\nemitted onStopComplete(STATUS_OK) and scheduled its own backoff start().\nVideoManager meanwhile restarted every receiver about 1 s after any\nonStopComplete, and 1 s after any failed start. The second start\ndefeated the exponential backoff, autoReconnect=false did not stop\nrestarts, and whichever start() lost reported STATUS_INVALID_STATE.\n\nThe receiver is now the single owner of recovery from failures.\n- GstVideoReceiver reports a stop it made itself with\n  onStopComplete(STATUS_FAIL), documented on VideoReceiver, and\n  reconnects with backoff only while autoReconnect is set.\n- A failed start, including a reconnect attempt, also schedules the\n  next attempt, so the backoff keeps growing until frames flow again.\n- End of stream follows the same path instead of a plain stop.\n- VideoManager restarts a receiver only after a stop that\n  _restartVideo() requested; it no longer retries after\n  onStartComplete(STATUS_FAIL).\n- stopVideo() now always calls stop(), so a receiver that is waiting\n  to reconnect is cancelled even though VideoManager already counts it\n  as stopped. It also no longer restarts the receiver a second later.\n\nThis keeps the QtMultimedia backend working: it never stops itself or\nfails a start, and its settings-driven restarts still go through\n_restartVideo().\n\nThe start/stop completion handling moves into\n_connectReceiverLifecycle() so a new VideoManagerRestartTest can\nexercise it with a synchronous fake receiver. It checks a requested\nrestart, no restart after a self-stop or a failed start, and that\nstopVideo() stops a receiver waiting to reconnect. GstVideoReceiverTest\nadds a check that retries after failed starts back off (1 s, then 2 s)\nand then recover, and a stream-loss test showing one reconnect with\nautoReconnect and none without.\n\nFixes review R#10.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(VideoReceiver): disable QoS on every decoder, size from sink caps\n\nDecoder QoS was disabled by iterating decodebin3's children once, on\nthe first decoder pad, from a streaming thread. The loop ignored\nGST_ITERATOR_RESYNC, and a decoder decodebin3 plugs later (after a caps\nchange or reconfigure) kept qos=TRUE, which brings back the cascading\ndrops on live streams. A handler on decodebin3's deep-element-added\n(GstBin, since 1.10) now turns QoS off on each decoder as it is added,\nbefore it sees data, and records its name. The name is updated on the\nworker, and decoderStatsChanged is posted to the receiver's own thread,\nfor the 1 Hz QoS drain too.\n\nThe video size came from a caps query on the encoded side of the\ndecoder valve, which can return unfixed caps (QSize(0,0)). It also had a\ndead branch reading a \"video-orientation\" caps field that GStreamer\nnever sets, and an unused caps query on the decoder pad. videoSizeChanged\nis now emitted from the sink's qgc-caps-info message, which carries the\nnegotiated raw size. Nothing consumes the image-orientation tag, so\norientation is not reported. Link failures in the touched code log as\nwarnings.\n\nTests check that every decoder in the decode branch has QoS off with\nits name reported, and that the size comes from the real\nqgcvideosinkbin's negotiated caps.\n\nFixes review R#14 and R#15; part of R#18.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* refactor(VideoReceiver): split GstVideoReceiver into focused components\n\nPure moves unless noted; pipeline topology, element properties and log\ntext are unchanged.\n\n- StreamWatchdog owns the frame times (monotonic), the 1 s timeout\n  floor, the source/decoder stall decision and the 1, 2, 4 ... 30 s\n  backoff that restarts after a pipeline that delivered frames. Times\n  are passed in, so the new GstVideoReceiverComponentsTest checks the\n  policy without a clock.\n- PipelineDotDumper takes the fourteen GST_DEBUG_BIN_TO_DOT_FILE sites\n  and the CacheLocation snapshots behind dump() and snapshot().\n- RecordingBranch owns the recorder queue and valve, the per-recording\n  file sink, the keyframe gate, the EOS drain and the recorder's bus\n  traffic. RecordingFinalizer becomes its own unit-tested class: only\n  the armed sink and its children settle a recording, and the first\n  outcome sticks. Elements join the pipeline as they are created, so a\n  failed start has one cleanup path.\n- DecodingBranch owns the leaky display queue and valve, the held video\n  sink, decodebin3 insertion, the frame probe, stopDecoding()'s teardown\n  and the decoder statistics; the two copies of \"insert the decoder and\n  open the valve\" become one function.\n- BusMessageRouter holds the sync handler and its attach/detach\n  lifetime, so all posting-thread code is in one file; unused includes\n  such as QUrl and QQuickItem go (R#21).\n- The GStreamer README lists the new components.\n- GstVideoReceiverTest no longer QSKIPs in init(), which also skips\n  cleanup() and made UnitTest's destructor abort the run in builds\n  without GStreamer streaming or a required plugin.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(VideoReceiver): keep dot dumps per receiver and free of credentials\n\nFixes review R#16:\n- Every receiver named its pipeline \"receiver\" and used the same dump\n  tags, so the main and thermal streams overwrote each other's dumps. The\n  pipeline is now \"receiver-<name>\" (receiver-videoContent,\n  receiver-thermalVideo) and every dump file starts with that name.\n- Native GST_DEBUG_DUMP_DOT_DIR dumps used GST_DEBUG_GRAPH_SHOW_ALL, which\n  prints non-default element properties such as rtspsrc's user-id and\n  user-pw, also for the QML \"for bug reports\" dumpPipelineGraph(). All\n  dumps now use the property-free kDiagnosticDotGraphDetails.\n- dumpPipelineGraph()'s tag went into the file name unchecked, so \"../\"\n  or a path separator escaped the dump directory, and the CacheLocation\n  writer decoded it as Latin-1. The tag is now reduced to letters, digits,\n  '-' and '_' (40 characters at most) for both kinds of dump.\n- A watchdog timeout now also writes the CacheLocation snapshot, as the\n  README promised.\n- All dumps already ran on the worker; PipelineDotDumper now documents it.\n\nwritePipelineDot() takes the target directory, so the CacheLocation and\nGST_DEBUG_DUMP_DOT_DIR policy lives in PipelineDotDumper and the writer is\nunit-tested against a temporary directory. GStreamerTest's\n_testWritePipelineDotReturnsEmptyOnWriteFailure provoked its failure with\na \"missing-dir/\" tag, the unsafe behaviour this removes; it now blocks\nthe directory with a regular file instead. The README's Pipeline\nObservability section describes the new file names and detail level.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(VideoReceiver): keep the pipeline PLAYING when a recording starts\n\nsplitmuxsink goes to PAUSED asynchronously and commits only once its first\nfragment opens, at the next keyframe. Its ASYNC_START travelled up through\nthe recording bin to the pipeline, which therefore lost state on every\nstartRecording(): PAUSED for up to a GOP, then a re-commit to PLAYING.\nWhen the file sink failed before committing (unwritable path), the\npipeline stayed in PAUSED and every later recording wrote an empty file;\nreceiver-2 worked around that by setting the pipeline back to PLAYING\nafter a recorder error.\n\nThe recording bin now sets async-handling, so it waits for splitmuxsink\nitself (upstream gstbin.c: such a bin counts as top level and posts no\nASYNC_START to its parent). The pipeline stays PLAYING throughout, and the\nPLAYING re-assert after a recorder error is removed. Without\nasync-handling, both the new _testRecordingStartKeepsPipelinePlaying\n(pipeline reads PAUSED->PAUSED right after startRecording) and\n_testRecordingErrorKeepsStreaming (the next file is empty) fail.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(VideoReceiver): link only video RTP streams in the source bin\n\n- GstScoped.h gains std::unique_ptr owners with noexcept deleters (no\n  g_autoptr, so MSVC keeps building) and adopt* helpers for GstElement,\n  GstPad, GstBus, GstCaps, GstMessage, GstEvent, GstSample, GstBuffer,\n  GstStructure, GstIterator, gchar* and GError. (Part of R#20)\n\nSource factory (R#13, with R#18/R#20 applied):\n- Every application/x-rtp pad counted as video, so an RTSP camera\n  listing audio first had its audio linked and the video pad rejected as\n  \"already linked\". RTP pads need media=video, and rtspsrc's\n  select-stream skips non-video SDP streams before SETUP, deciding on\n  the SDP media field because the caps are still application/x-unknown.\n- RTSP never got the rtx-delay/rtx-max-retries policy, since rtspsrc\n  doesn't forward it to its rtpbin; it is applied through new-manager ->\n  new-jitterbuffer.\n- The dynamically inserted rtpjitterbuffer was removed without a NULL\n  transition (\"Trying to dispose element ... in PLAYING\"); it is\n  detached and then set to NULL.\n- Plain udp:// and MPEG-TS no longer request retransmission: without an\n  rtpsession or RTCP back-channel, udpsrc drops the requests.\n- gst_bin_add and gst_element_add_pad consume a floating argument even\n  when they fail, so the old cleanup unref'd it twice.\n- The factory uses the GstScoped owners and logs expected failures as\n  warnings.\n\nTests: retransmission off on plain UDP, the RTSP rtx timing, a\nselect-stream row with realistic pre-SETUP caps, audio-before-video\nlinking, and an end-to-end rtspsrc against an in-test RTSP responder\n(audio first in the SDP) whose first SETUP must target the video track.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(VideoReceiver): classify decoder families with one prefix table\n\nDecoder families were classified in three places that disagreed:\nisHardwareDecoderFactory used substring tags, per-option rank arrays listed\nfactory names by hand, and availableDecoderFamilies had its own prefix\nlist. The substring match misread software decoders as hardware whenever\ntheir names contained a family tag. On this host avdec_wnv1,\navdec_dsicinvideo and avdec_idcinvideo all count as hardware via \"nv\", so\nForceVideoDecoderHardware prioritised them.\n\nReplace all three with one kDecoderFamilyPrefixes table of\n{prefix, family, isHardware}. Matching is by prefix, case-insensitive, and\nthe first match wins, so the specific rows (Android software wrappers,\nlegacy vaapi) sit ahead of the general ones. The new\ndecoderFamilyForFactory() reads the table and serves both\navailableDecoderFamilies() and the ForceVideoDecoder* rank overrides. Those\noverrides now rank every installed decoder in the family, not only a\nhard-coded list of names, so the options always cover the decoders that\navailableDecoderFamilies() advertises. The Linux zero-copy steering bumps\nva* decoders through the same path. The platform-specific legacy-vaapi,\nV4L2 stateless and D3D11/D3D12 alignment lists are not family\nclassification and stay as they are.\n\n_testIsHardwareDecoderFactory becomes data-driven, with rows for the\nmisclassified software decoders. A new _testDecoderFamilyForFactory pins\nthe name-to-family mapping.\n\nFixes review R#25.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(VideoReceiver): fix Windows env setup and the mock RTSP server\n\nGStreamer environment (R#22, checked against the upstream sources):\n- qputenv's _putenv_s decodes UTF-8 in the ANSI code page while GLib\n  reads the wide environment, so a non-ASCII install path reached\n  GStreamer corrupted. Windows uses g_setenv and reads PATH with\n  qEnvironmentVariable.\n- _systemGioIsNew's RTLD_NOLOAD dlopen returned the bundled GIO and\n  could load a second, system libgio; glib_check_version(2, 76, 0)\n  answers the same question without loading anything.\n- prepareEnvironment() returned function statics; _setGstEnvVars()\n  returns its result by value.\n- The macOS, Windows and Linux bundle discovery share a table-driven\n  BundleLayout, which removes an unreachable validation branch.\n- GST_PLUGIN_PATH* duplicated GST_PLUGIN_SYSTEM_PATH*, so the registry\n  scanned every plugin twice; it is now cleared instead of set.\n- README: a missing scanner only warns, and GST_REGISTRY_FORK=no scans\n  in-process.\n\nMock RTSP server (code part of R#23):\n- A g_main_loop_quit() that arrived before the server thread reached\n  g_main_loop_run() was lost and join() hung; the quit is now invoked\n  on the server's context.\n- The host argument was ignored and the server listened on every\n  interface; gst_rtsp_server_set_address binds it.\n\ngst-rtsp-server is not installed on the development host; that branch\nwas syntax-checked against the upstream 1.20 signatures.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* refactor(VideoReceiver): remove dead code and scope the receiver's refs\n\n- The processedFrames, droppedFrames, currentJitterNs, qosProportion and\n  qosQuality properties had no reader, yet every QOS message wrote five\n  atomics and the watchdog polled them. They go with the QOS routing;\n  decoderName stays, notified by decoderNameChanged. The never-requested\n  JitterBuffer::Buffered, commented-out members and a stale FIXME go\n  too. (R#19 partial)\n- Every ref the receiver and its components own is held in a GstScoped\n  owner; borrowed pointers stay raw and say so. disposeChild() replaces\n  six copies of \"remove, set NULL, wait\" (changes to READY/NULL commit\n  at once, so the wait was unnecessary) and firstSrcPad() two copies of\n  grabFirstSrcPad. RecordingBranch::makeFileSink() returns an owned\n  ref, which fixes a double unref after a failed gst_bin_add();\n  _testFailedRecordingStartLeavesBranchUsable fails without it. (R#20)\n- Runtime failures (element creation, bin adds, pads, links, a bad URI)\n  log qCWarning instead of qCCritical, which marks coding errors and\n  fails tests; messages drop function-name prefixes, and the stats\n  summary is qCDebug. (R#18)\n- Magic numbers become named constants (log intervals, the 40 ms\n  latency floor, the stall factor and backoff bound, the display queue\n  depth, VideoManager's stall timeout and restart delay), and unused\n  includes go from GStreamer.cc and VideoManager. (R#21, R#24 partial)\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* feat(VideoReceiver): save screenshots from the GStreamer receiver\n\nGstVideoReceiver::takeScreenshot always reported STATUS_NOT_IMPLEMENTED,\nso VideoManager::grabImage (also used for camera photos in video mode)\nnever wrote a file with the GStreamer backend.\n\nIt now saves the frame on display: the QVideoSink of the receiver's\nVideoOutput widget, which attachAppSink() binds to the qgcqvideosink, is\nasked for its current frame (thread-safe in Qt Multimedia), and\nQVideoFrame::toImage() converts it, mapping GPU-backed frames back to the\nCPU, as QtMultimediaReceiver does. This runs on the caller's (GUI)\nthread, which owns the widget, instead of hopping to the worker. A\nmissing sink or frame, or a failed save, reports STATUS_FAIL with a\nwarning.\n\nNew GstVideoReceiverTest::_testScreenshotSavesDisplayedFrame binds a\nreal qgcvideosinkbin to a QQuickVideoOutput, checks that a screenshot\nfails before any frame arrives and that one taken while streaming is a\n320x240 image.\n\nFixes review R#19 (takeScreenshot).\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(VideoReceiver): keep whole snapshot tags and refresh the README\n\n- PipelineDotDumper::snapshot() passes \"receiver-<stream>-<tag>\" to\n  writePipelineDot(), which ran it through dotFileTag() again. Its\n  40-character cap then cut built-in tags: a watchdog snapshot was saved\n  as \"receiver-videoContent-pipeline-watchdog--<time>.dot\". The cap is\n  now 57 characters, what a 255-byte name allows next to the\n  \"-<time>.dot\" suffix at 4 UTF-8 bytes a character, so only very long\n  dumpPipelineGraph() tags are cut. A \"receiver snapshot\" row in\n  _testPipelineDotStaysInDirectory fails under the old cap.\n- README: the component table covers screenshots, robust MP4/MOV muxing\n  and GStreamerHelpers; Supported protocols lists the URI schemes\n  GstSourceFactory accepts; a new \"Automated tests\" table describes the\n  three receiver suites, their labels and how to run them; logging and\n  pipeline observability match the code.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(VideoReceiver): report per-sink stats and release frames on stop\n\n- The receiver logged HwBuffers::formatPathStats(), a read-and-clear of\n  process-wide counters, so with two receivers stopping one logged the\n  other's frames under its URI and reset its counts. It reads its own\n  qgcqvideosink's stats through DecodingBranch::sinkPathStats(),\n  relative to a baseline taken with the sink, so each session reports\n  only its own frames. Render-time map failures belong to no sink and\n  are reported by takeExtraPathStats(); formatPathStats() is removed.\n  (R#24, S#10)\n- The QVideoSink kept its last frame, and the GstSample and decoder\n  buffer behind it, after the pipeline stopped. prepareForRelease()\n  would unbind the element for good, so a new releaseFrame() clears\n  only the frame and DecodingBranch calls it whenever it takes the sink\n  out of the pipeline. _testStopReleasesDisplayedFrame fails without it.\n- QGCQVideoSinkController's refreshLatency() (a GUI-thread LATENCY query\n  whose answer was dropped; the sink takes its latency from the LATENCY\n  event) and _stateMutex (its state is touched on one thread only) are\n  removed. (R#19 leftovers)\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* chore(VideoReceiver): update GStreamer.cc comments and includes\n\n- createVideoSink: the bin passes gpu-zerocopy to the qgcqvideosink it\n  constructs, which builds its GPU context from it (sink-2); nothing reads\n  it back from the bin any more.\n- gst_init_static_plugins() is generated from\n  cmake/GStreamer/gst_static_plugins.c.in by qgc_gst_generate_static_init()\n  (cmake-3), not by Android/IOS.cmake.\n- gstqgc/gstqgcqvideosink.h is unused since setupQVideoSinkElement no\n  longer pushes a context into the sink.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* refactor(VideoManager): rename GStreamerFrameMap to GstQgcFrameMap\n\ngstqgc/ names its GObject element units in lowercase (gstqgcqvideosink.cc)\nand its helpers GstQgc*; GStreamerFrameMap was the one leftover name.\ngit mv plus the includers, the gstqgc CMake list, the log category\nvariable (the \"Video.GStreamer.FrameMap\" filter name is unchanged) and\ncomments.\n\nTouching the include lines made the clang-format hook re-sort the include\nblocks of the four HwBuffers test files, which also drops a duplicate\n#include \"GStreamer.h\" in each.\n\nReview S#26 (rest; gstqgcelement.cc was renamed in sink-2).\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* test(VideoManager): fix GStreamer-off skips and format the test CMake\n\n- Without QGC_GST_STREAMING, VideoManagerInitTest::init() called\n  UnitTest::init() and then QSKIPped. A skip in init() also skips\n  cleanup(), so ~UnitTest's _cleanupCalled assertion aborted the run.\n  The test functions already skip on their own, so init() only calls\n  UnitTest::init(). Pre-existing on master.\n- test/VideoManager/GStreamer/CMakeLists.txt failed the cmake-format and\n  cmake-lint hooks; it is formatted with cmakelang 0.6.13, its comment\n  is wrapped and the Receiver/ entries are sorted.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* docs(VideoReceiver): fix stale references left by the merged streams\n\n- G/CMakeLists.txt: QGC_GST_BUILD_TESTING no longer guards clearForTest\n  (removed with GstContextBridgeRegistry in hwplat-3); name the hooks it\n  guards now.\n- README: GStreamerTest is an Integration test (CMake and\n  UT_REGISTER_TEST), not Unit; list the frame release on stop among\n  GstVideoReceiverTest's coverage and in QGCQVideoSinkController's role.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(VideoManager): don't shadow GstBaseSink's stats property\n\nsink-2 gave qgcqvideosink a read-only \"stats\" property for its per-sink\nframe accounting. GstBaseSink already has a \"stats\" property (Since 1.18,\nso on every supported version) with average-rate/dropped/rendered, and\nthe subclass property silently replaced it: gst-inspect and any generic\ntool reading a sink's \"stats\" got QGC's qgc-video-sink-stats structure\ninstead.\n\nThe property is now \"frame-stats\" (checked against GstObject,\nGstBaseSink and GstVideoSink property names on upstream main; no other\nclash). Its reader in DecodingBranch, the HwBuffers::formatSinkStats()\nand telemetry docs, the README and the tests follow.\n\n_testQgcQVideoSinkKeepsBaseSinkStats checks that \"stats\" resolves to\nGstBaseSink's pspec and returns its structure, and that \"frame-stats\" is\nthe sink's own; it fails with the old property name.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* test(VideoReceiver): destroy the receiver before its signal spies\n\nGstVideoReceiver emits its signals on its worker thread (recordingStarted\non a streaming thread), and QSignalSpy takes them through a direct\nconnection on the emitting thread. Every GstVideoReceiverTest function\ndeclared its spies after the receiver, so they were destroyed first while\nthe receiver could still be emitting into them: whenever a test ended or\nfailed with a live pipeline (watchdog timeout, reconnect, late first\nframe). QSignalSpy's teardown is not synchronized with a delivery in\nflight, so such an overlap is a use-after-free of the spy.\n\nA scratch run that queues onStopComplete emissions on a real receiver and\ndestroys the spies first segfaults in QMetaObject::metacall on the worker\nthread every time under ASan; with the receiver destroyed first it is\nclean. Each test now declares destroyBeforeSpies() after its spies, so the\nreceiver, whose destructor stops the pipeline and joins its worker, goes\nfirst.\n\nThis is one candidate for the \"malloc(): unaligned tcache chunk detected\"\nabort seen once in ~120 stress runs. That abort did not reproduce, and its\ncore shows the whole process stalled for ~7 s just before it.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* style(clang-format): add an Objective-C section\n\nThe only section in .clang-format names Language: Cpp, so clang-format\nrefuses Objective-C++ sources (\"Configuration file(s) do(es) not support\nObjective-C\") and the pre-commit hook fails on\nHwBuffers/apple/GstIOSurfaceVideoBuffer.mm.\n\nAdd a Language: ObjC section with the same settings. A section that names\nits language inherits nothing from the others, so the keys are repeated;\na language-less default section would instead also claim the Java and\nother non-C++ sources clang-format currently leaves alone. The effective\nC++ configuration is unchanged, and ObjC differs from it only in Google's\nObjC default for AlwaysBreakBeforeMultilineStrings.\n\nFormat the lines this branch changes in GstIOSurfaceVideoBuffer.mm. Its\ninclude block is regrouped like the other HwBuffers backends', with the\nIOSurfaceRef.h note kept on that include.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* style(cmake): apply cmake-format and cmake-lint to the touched files\n\nCI's pre-commit job enforces cmake-format and cmake-lint on whole files,\nso every CMake file this branch touches must pass them, pre-existing\nregions included. Behaviour is unchanged.\n\n- cmake-format (cmakelang 0.6.13, .cmake-format.yaml) over the 33\n  touched files that failed it: whitespace, argument wrapping and\n  command-name case only.\n- cmake-lint in cmake/GStreamer: lowercase positional parameters (the\n  PROJECT_NAME parameter that shadowed CMake's variable becomes\n  app_name), one-line docstrings, long messages split into adjacent\n  strings, foreach(RANGE) with an explicit step, and stated suppressions\n  for the discovery chains and resolvers that keep their shape.\n- cmake-lint in the shared BuildConfig.cmake, PrintSummary.cmake,\n  modules/Download.cmake and platform/Android.cmake: lowercase\n  parameters, docstrings, split messages and one stated suppression for\n  qgc_resilient_download.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* refactor(VideoReceiver): simplify the receiver, its helpers and comments\n\nFirst simplification pass over the receiver (review items in brackets).\n\n- BusMessageRouter only forwarded into GstVideoReceiver privates through\n  a friend, so its handlers become receiver members and its two files\n  go; the threading contract is unchanged.\n  HwBuffers::onBusSyncMessage() takes just the message. (4, 16, H18)\n- disposeChild() resolves the parent itself and serves all eight\n  teardown sites, addToBin() moves to GStreamerHelpers for every\n  floating-ref add, unused GstScoped owners go, and the single-caller\n  configureJitterBuffer() is inlined. (2, 3, 9, 10)\n- forEachVideoDecoderFactory() replaces four hand-written walks over the\n  video decoder factories, ranks are set on the held feature, and the\n  five family options share one case. GStreamerTest passes unchanged\n  (185 pass, 16 skip). (7, 8)\n- Unused code goes: an always-false _onWorkerThread() re-queue,\n  StreamWatchdog::stop() (start() resets the same state), a stale\n  friend, RecordingBranch::state(), a redundant DecodingBranch check and\n  QGCQVideoSinkController's AutoConnection hop. (1, 5, 11, 12, 13, 16,\n  18)\n- The keyframe probe stays until _shutdown() removes it instead of\n  removing itself, so its id is a plain worker-owned gulong rather than\n  an atomic cleared with compare_exchange, at the cost of one early\n  return per recorded buffer. (6)\n- RecordingBranch comments drop upstream history and a wrong\n  message-forward explanation, the video-sink ref protocol is explained\n  once, and the README rows are one sentence each. (15, 17, 19)\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* refactor(gstreamer): simplify targets, downloads, policy and dispatch\n\nFirst simplification pass over the GStreamer CMake modules.\n\n- Unread *_FOUND outputs go (requested optional components keep\n  theirs), and platform/PkgConfigTargets.cmake folds into one\n  _qgc_gst_create_sdk_targets in Targets.cmake that reads the\n  Orchestrator's variables directly. Generated build commands are\n  unchanged.\n- qgc_gst_acquire_sdk reaches qgc_resilient_download through one\n  _qgc_gst_download_archive instead of two single-caller wrappers whose\n  options nobody passed, and the extraction stamp records only the\n  archive hashes.\n- The plugin policy helpers fold into gstreamer_missing_required, static\n  layouts take GSTREAMER_STATIC_PLUGINS as available, the DMABuf probe\n  is called directly, PrintSummary reads the resolved-root cache entries\n  and the SDK fingerprint adds only the user's PKG_CONFIG_ARGN.\n- qgc_gst_platform sets the platform name, version variable and plugin\n  key in one if/elseif and the helpers are called by name. Windows'\n  arm64/x86_64 lookups, Android's file-staging pair and Apple's package\n  validator are folded, Android's fixed SDK paths become locals, and\n  build.gradle lists '../extra_assets' directly. test_platform checks\n  all five platforms.\n- test_orchestrator's four fresh-configure scenarios become one\n  sequential \"reconfigure\" scenario, and tests that restated others or\n  could not fail are dropped; with the other changes above,\n  ctest -L 'FindModule|CMake' runs 84 tests instead of 91.\n- The Helpers.cmake index, which duplicated the README and went stale,\n  becomes a short pointer, and stale Orchestrator, Android and\n  cmake/README.md comments are trimmed.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* build(gstreamer)!: drop the legacy GSTREAMER_ROOT aliases\n\nThe Orchestrator still accepted GSTREAMER_ROOT (the upstream\nFindGStreamer.cmake spelling) and GStreamer_ROOT (find_package's\n<Package>_ROOT) as deprecated fallbacks for GStreamer_ROOT_DIR, with a\nDEPRECATION message. Nothing in the repository sets them: a search of\ncmake/, src/, test/, .github/, tools/, deploy/, android/ and docs found\nno other reference. The fallback, its message and the intermediate\n_qgc_gst_user_root variable are removed.\n\nBREAKING CHANGE: -DGSTREAMER_ROOT=<dir> and -DGStreamer_ROOT=<dir> are\nnow ignored without a warning, and configure discovers or downloads the\nSDK as if no root had been given. Set GStreamer_ROOT_DIR instead.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(gstreamer): keep the iOS app on GStreamerMobile's GStreamer core\n\nRegistering only the allowlisted plugins on iOS shrank GStreamerMobile from\n~200 MB to ~50 MB, so it no longer contained gst_debug_bin_to_dot_data and\ngst_debug_bin_to_dot_file, which QGC calls for pipeline graph dumps but none\nof the 27 registered plugins pulls in. The app then linked them from the\nmerged static archive, and with them ~410 core objects: a second GStreamer\ncore. At startup GLib reported \"cannot register existing type\n'GstPluginFeature'\", video init timed out, and the iOS simulator boot test\nfailed. The app binary from CI defined 792 gst_* symbols; master's defines 3.\n\nForce QGC's directly-called core functions into GStreamerMobile with -u\n(QGC_GST_IOS_APP_CORE_SYMBOLS) so the app resolves them there, as it did when\nevery plugin was registered. A post-build check fails the iOS build when the\napp binary defines core symbols, naming the list to extend, so this can't\nregress silently into a runtime failure again. Run against the CI binaries,\nthe check passes master's app and fails the broken one.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* refactor(HwBuffers): drop dead import paths and share backend code\n\nFirst simplification pass over HwBuffers (review items in brackets).\n\n- Dead paths go: the DMABuf tiled-modifier import (every non-LINEAR\n  modifier is rejected first) and the gst-vulkan import, which\n  admitImport() always refused, so the Vulkan path again records\n  VulkanNoSync as on master. The remaining Vulkan helpers move into the\n  DMABuf->Vulkan import. (3, 4, 15)\n- kCompiledPaths is a constexpr list returned by paths(), replacing the\n  runtime registry and initializeOnce(); test-only overloads go, and the\n  CUDA export latch trips inside exportToDmaBuf(). (2, 9, 13)\n- Telemetry reports each wait once: DMABuf no longer counts every\n  producer wait twice; reuse, waits and fence timeouts print for every\n  path when nonzero; and never-recorded counters and fallback reasons\n  and the global demotion counter go. Sink counters move into the sink.\n  (1, 5, 10, 12, 14)\n- wrapPlanes() records the QRhi, size, format and handles it imported,\n  so the base class matches reused bundles, and the seven sourcePath()\n  overrides and per-backend matches() go. (6, 16)\n- GstD3D11/GstD3D12VideoBuffer and their pool proposals become one\n  template each, driven by the resolver traits; the redundant Q_OS_WIN\n  guards and the single-override logHandoff() virtual go. (7, 21)\n- GstHwVideoBuffer and MapThroughGstVideoBuffer share\n  CpuVideoFramePool::FrameMapping, qgcvideosinkbin's setup() adopts the\n  sink and capsfilter once for both paths, and the DMABuf env test hook\n  reads readHwBufferEnvConfig(). (11, 17, 19)\n- _qgc_gpu_path_blocker() folds into its one caller; configure output\n  and compile_commands.json are unchanged. (8)\n\nGStreamerTest: 185 -> 181 passed (the removed admitImport and\ntiled-latch rows), 16 skipped. D3D, IOSurface and AHardwareBuffer code\npassed the stub-header syntax checks.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* test(VideoReceiver): ignore libproxy noise in the RTSP SETUP test\n\nmacOS runners carry a system proxy bypass entry (169.254/16) that libproxy\ncannot parse; its GLib warning reaches the GStreamer log bridge and fails the\ntest under strict log checking although RTSP setup succeeds.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(VideoReceiver): name the failing element in pipeline error logs\n\nPipeline errors such as baseparse's \"No caps set\" carry no debug text, so the\nwarning alone could not tell which element failed. Log the source object's path\nwith the message.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(VideoManager): don't double-unref failed sink-bin adds\n\nGstQgc::BinChain unreffed an element after gst_bin_add() rejected it and a\nghost pad after gst_element_add_pad() rejected it. Both GStreamer calls\nalready ref_sink + unref their argument on the failures a new element or\npad can hit (gstbin.c duplicate_name/no_function, gstelement.c\nname_exists), so a floating element or ghost pad was unreffed twice.\n\nadopt() now sinks a floating element into a full ref first and always\ndrops that ref after gst_bin_add(), which consumes the caller's ref\nexactly once whether it was floating or not. ghostSink() only forgets the\npad on failure.\n\nNew test: a floating element with a duplicate name, held alive by an\nextra ref of the test's own, survives a failed adopt() until that ref is\ndropped. It fails before this change (the element is destroyed under the\ntest's ref).\n\nReview B-1.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(VideoReceiver): make Qt Multimedia screenshots work via shared code\n\nGstVideoReceiver and QtMultimediaReceiver each read the frame on display\nfrom a QVideoSink, converted it with toImage() and saved it. The Qt\nMultimedia copy also rejected any frame with !isReadable(), but Qt's\nisReadable() is `mapMode & ReadOnly`, false for every unmapped frame, so\nits screenshots always failed.\n\nThe GStreamer implementation moves into a non-pure\nVideoReceiver::takeScreenshot() (new VideoReceiver.cc, logging under\nVideo.VideoReceiver). It reads the sink through widget()'s public\nQQuickVideoOutput \"videoSink\" property, so the base class needs no\nprivate Qt header; VideoManager sets the widget for every backend before\nany screenshot. Both overrides and the restart test's no-op fake are\ndeleted, and GstVideoReceiverTest expects the new log category.\n\nNew test: a QtMultimediaReceiver saves an unmapped CPU frame shown in its\nwidget's sink. It fails before this change (\"Screenshot Frame is\nInvalid\").\n\nReview B-2.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(HwBuffers): offer one DMA_DRM format set, size planes by component\n\n- The EGL-derived DMA_DRM caps and the forced LINEAR ones\n  (QGC_GST_OFFER_DMA_DRM_LINEAR) picked their formats in two places that\n  had drifted: a hand-coded fourcc->name map also offered YV12 while the\n  format table's kOfferLinearDmaDrm flag left it out, and the forced\n  list came out in hash order. Both builders now take the table's\n  kOfferLinearDmaDrm formats and map EGL fourccs with\n  gst_video_dma_drm_fourcc_to_format(). YV12 joins the LINEAR set\n  (imported exactly like I420). A new test checks the forced LINEAR\n  caps. (B-3)\n- The per-plane EGLImage import passed plane indices to the\n  GST_VIDEO_INFO_COMP_* macros, the bug class already fixed in the CPU\n  path. It is latent for every format drmFourccForPlane() maps; the\n  plane helpers move into GstHwVideoInfo, shared by the CPU pool and the\n  importer. (B-4, C-17 option B)\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* refactor(VideoReceiver): reuse shared helpers in the receiver and sink\n\nSecond simplification pass, receiver side (review items in brackets).\n\n- StreamWatchdog uses the app's ExponentialBackoff (same 1 ... 30 s\n  sequence); the dot-graph helpers move into PipelineDotDumper and write\n  through QGCFileHelper::atomicWrite(); GStreamer::addTeeBranch() builds\n  the tee ! queue ! valve head both branches duplicated, checking each\n  add; and GStreamer::PadProbe owns a probe id with its pad. (C-4, C-6,\n  C-7, C-8)\n- qgcqvideosink's frame-stats format (PathStats, the field names and\n  formatSinkStats()) moves next to the sink with GstQgc::frameStats() as\n  the one reader, the qgc-caps-info message gets kCapsInfoMessage and\n  parseCapsInfo(), and HwBuffers::onPipelineError() takes the parsed\n  error. (C-5, C-9, C-12)\n- applyPrefixRank() over forEachVideoDecoderFactory() replaces the\n  hand-written vaapi, v4l2sl and D3D rank lists, so family members they\n  missed (other legacy vaapi decoders, a second device's v4l2sl, a\n  secondary adapter's D3D) follow their family; describeDecoderFactory()\n  builds the description both decoder logs used. (C-11, C-13)\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* refactor(HwBuffers): count telemetry through one enum, share helpers\n\n- GstHwPathTelemetry's six hand-written record/take/peek sets become a\n  Counter enum with record/peek/take(path, Counter) and a table of\n  labelled counters; the stats line keeps every label and value. (C-15)\n- CpuVideoFramePool::FrameMapping gains mapFrame()/frame(), used by\n  copyFromBuffer() and the GLMemory import; GstQgcCaps builds each\n  memory-feature fragment with one helper and GstDmaDrmCaps shares the\n  drm-format append and prefix; GstEglHelpers' imageTargetTexture2D()\n  and destroyImageKHR() replace per-file eglGetProcAddress() lookups.\n  Caps strings, map flags and unmap order are unchanged. (C-16, C-18,\n  C-19)\n\nD3D and AHardwareBuffer code was syntax-checked against the stub\nheaders.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* refactor(VideoManager): hold refs in scoped owners, fix stale comments\n\n- Manual unref/free pairs move to GstScoped.h owners: the bridges'\n  makeContext() returns a new GstContextPtr, and the GL bridge's EGL\n  display, the Vulkan physical device, the proposed pool, the bin's\n  caps, isHardwareDecoderFactory()'s and qtGstLog()'s strings and the\n  controller's element ref are scoped. Ref counts are unchanged. (C-10)\n- Stale or wrong comments are fixed (the controller's \"bus pump\", the\n  receiver's topology diagram, Qt line numbers), each rationale is\n  stated once, \"GPU path\" replaces \"HW path\" in comments, logs and the\n  README, and the reconnect contract stays on\n  VideoReceiver::onStopComplete. (D-2, D-4, D-7, D-9)\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* refactor(gstreamer): reuse shared config, download and slice helpers\n\nSecond simplification pass over the GStreamer CMake.\n\n- cmake/modules/BuildConfigReader.cmake's qgc_config_read() is the one\n  build-config.json reader (plugin lists, checksum pins, versions).\n  BuildConfig.cmake stops caching per-platform version variables, and\n  Json.cmake and test_json go, since the schema check covers them. A\n  missing gstreamer.plugins.common now fails configure.\n- The schema requires the iOS CA bundle URL and checksum, so the\n  unverified fallback and QGC_GST_ALLOW_UNVERIFIED_CA go.\n- The checksum sidecar is fetched with qgc_resilient_download,\n  QGC_GST_DOWNLOAD_INACTIVITY_TIMEOUT gives way to the generic one, and\n  IOS.cmake uses qgc_find_ios_xcframework_slice(), which now fails when\n  no slice matches every architecture instead of taking the first.\n- Android's plugin Java, fonts and CA bundle are copied at configure\n  time (file(COPY_FILE ONLY_IF_DIFFERENT)) instead of by per-file build\n  rules.\n- No-op find_library guards and the save/restore suffix macros go; the\n  Android ssl/crypto lookup uses the static-only suffix.\n- GStreamer.cc's _verifyPlugins reads the runtime-required plugins and\n  their alternates from QGC_GST_RUNTIME_REQUIRED_PLUGINS, which CMake\n  sets from PluginPolicy.cmake, instead of a hand-copied array. (C-14)\n- The HwBuffers test hooks compile under QGC_UNITTEST_BUILD, and the\n  PUBLIC QGC_GST_BUILD_TESTING define goes.\n\nCMake tests: 86/86; GStreamerTest unchanged at 181 pass / 16 skip.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* refactor(gstreamer): move version floors to tools, relabel CMake tests\n\n- The check that the bundled platforms are at least 1.28 and that\n  gstreamer.version.minimum stays below it is a config-file check, so it\n  moves from test_version_policy.cmake to tools/validate_configs.py,\n  which already runs in pre-commit and CI, with tests.\n- FindGStreamer.cmake is gone, so its tests are renamed GStreamer.<test>\n  and labelled Unit;CMake;GStreamer, and `ctest -L CMake` runs them.\n  test_download_helper moves to cmake/tests as CMake.DownloadHelper,\n  both failure tables register through qgc_add_expected_failure_test,\n  and qgc_test_sandbox() replaces the repeated sandbox setup.\n\nCMake tests: 86/86 under -L CMake.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* refactor(tools): share GStreamer config helpers and narrow the CI cache\n\n- The SDK cache key hashed every cmake/GStreamer file, tests included,\n  so any edit re-downloaded about 1 GB per platform. It now hashes\n  build-config.json, Download.cmake and platform/*.cmake, and only\n  Windows, Android and iOS run the step.\n- build-gstreamer.py and gstreamer_archive.py default --version to the\n  platform's gstreamer.version through get_gstreamer_version() in\n  tools/common/build_config.py, replacing resolve_gstreamer_config.py\n  and its workflow step. Unused gstreamer_*version action outputs and\n  the Windows workflow's PATH juggling (verify_executable.py already\n  prepends the SDK's bin) go.\n- tools/common/gstreamer.py holds Download.cmake's package and mirror\n  URL layout for mirror_gstreamer.py, check_deps.py and the macOS and\n  Windows installers, and tools/tests/test_gstreamer.py runs the CMake\n  functions so the two can't drift. macOS downloads from /data/pkg/macos/\n  like CMake, and mirror uploads are verified against the build-config\n  pin when there is one.\n\nTools tests: 2028 passed; test_coverage_cache fails the same way without\nthis change (host ccache state).\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* build(linux): let the app set the AppImage GStreamer environment\n\ndeploy/linux/AppRun exported the GStreamer runtime environment before\nstarting QGC. GStreamer::prepareEnvironment() already does the same for a\nLinux bundle (GStreamerEnvironment.cc, Linux branch and _applyGstEnvVars)\nbefore gst_init:\n\n- QCoreApplication::applicationDirPath() is <APPDIR>/usr/bin, so the\n  plugin directory is <APPDIR>/usr/lib/gstreamer-1.0, as in AppRun.\n- The first scanner and ptp-helper candidates are AppRun's\n  usr/lib/gstreamer1.0/gstreamer-1.0 paths, set only when executable.\n- GST_REGISTRY_REUSE_PLUGIN_SCANNER=no and GST_REGISTRY_FORK=no.\n- GST_PLUGIN_SYSTEM_PATH(_1_0). GST_PLUGIN_PATH is cleared because it\n  would rescan the same directory.\n- With the bundled GLib (2.76+), GIO_MODULE_DIR is\n  <APPDIR>/usr/lib/gio/modules and GIO_USE_VFS=local, the values AppRun\n  exports. AppRun keeps exporting them, since they are outside the\n  GStreamer block.\n\nSo AppRun's GStreamer block is deleted. The stale \"AppRun sets GStreamer\nenv vars\" comment in GStreamerEnvironment.cc and the GStreamer README\nare updated.\n\nBehaviour changes:\n\n- AppRun overrode a GST_PLUGIN_PATH or GST_PLUGIN_SYSTEM_PATH the user\n  had set. The app respects it and then leaves the GStreamer environment\n  as the user set it, which is how non-AppImage Linux builds already\n  behave.\n- A missing bundled plugin directory or helper is now reported by the\n  app's qCWarning instead of AppRun's stderr.\n- The app's environment logic is not unit-testable here:\n  applicationDirPath cannot be faked. The AppImage needs a smoke test\n  (CI's \"Verify AppImage\" boot test runs it).\n\nverify_executable.py set GST_PLUGIN_PATH(_1_0) next to\nGST_PLUGIN_SYSTEM_PATH(_1_0) for build-tree executables. The system path\nalone loads the same plugins, so only it is set now. Its tests are\nupdated.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* docs(gstreamer): state each CMake rationale once, name GStreamer::mobile\n\nSeveral rationales were written in many places. Each is now stated once\n(review A2, A3, A5, A6, A8).\n\n- Discovery outputs: the variables every discovery function sets were\n  listed six times (the Orchestrator header and loop comment, and the\n  Android, Linux, macOS, Windows and iOS discovery docs). Platform.cmake\n  now states them once. Each discovery function lists only its search\n  order and extras, and the Orchestrator header lists only what it adds.\n- cmakelang: \"cmakelang 0.6.13 predates return(PROPAGATE)\" (x7) and the\n  file(ARCHIVE_EXTRACT) note (x2) become one cmake/README.md convention.\n  The `# cmake-lint: disable=` lines stay.\n- Single-core model: the Android plugin-archive doc no longer says \"no\n  longer\"; it says the target \"must not also link the archive by path\".\n  The app-carries-the-only-core asides in src/.../GStreamer/CMakeLists.txt\n  are dropped; Android.cmake's header and mobile-target comment keep it.\n- Stale Android copies: the staging doc says what is removed, not the\n  history.\n- HwBuffers/CMakeLists.txt: the PUBLIC-define rationale (x3) moves to the\n  file header, and the \"PRIVATE hid it\" history is dropped. The DMABuf\n  probe is credited to Orchestrator.cmake. Only comment lines change.\n- The GStreamer README's per-module list, which restated the module\n  headers, is replaced by a short pointer, and Helpers.cmake points at\n  the module headers.\n- The README's repeated GStreamer_ROOT_DIR paragraph goes, and its\n  re-fetch note moves into the caching section. The caching section also\n  stops saying the stamp holds the version (it holds the archive hashes).\n  The backoff numbers become \"exponential backoff\", the Android history\n  goes, and the test command drops QT_QPA_PLATFORM=offscreen, which\n  add_qgc_test already sets.\n- Prose and message prefixes say GStreamer::mobile instead of\n  GStreamerMobile, \"GStreamerMobile:\" or \"[GstMobile]\". iOS messages say\n  \"GStreamer iOS SDK\", \"iOS merged archive\" or \"iOS SDK bundle\" instead\n  of \"xcframework\", because the default 1.28 SDK is a .framework.\n  \"xcframework\" stays for the bundle kind and existing names. Target\n  names, and the gstreamer_mobile framework name that\n  .github/scripts/ios_package.py depends on, are unchanged.\n\nLinux configure status lines are unchanged.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* feat(VideoReceiver): select the Linux GPU sink bin at runtime\n\nLinux builds with both gst-gl and DMABuf compiled only the glupload\nqgcvideosinkbin and left QGC's direct DMABuf importer unreachable. They\nnow compile both bins and pick one per process from QGC_GST_GPU_BIN:\n\n- glupload (default, unchanged): glupload -> glcolorconvert -> GLMemory\n  2D caps; gst-gl imports LINEAR and vendor-tiled DMABuf.\n- dmabuf: DMA_DRM and memory:DMABuf caps straight into QGC's importer,\n  which binds LINEAR only and skips gst-gl's copy.\n\nValues are trimmed and case-insensitive; an unknown value warns once and\nkeeps the default. Single-variant builds ignore it (Android keeps\nglupload, DMABuf-only Linux the direct bin, Windows and Apple native\npassthrough). QGC_GST_BIN_USE_* become the capability macros\nQGC_GST_BIN_HAS_GLUPLOAD/_DIRECT_DMABUF, configure names both bins and\nthe default, and the README gains a \"GPU bin selection\" section.\n\nTests: the GPU-bin checks are data-driven per compiled bin, the DMABuf\nand GLMemory dispatch tests force their bin, _testGpuZeroCopyFallback\npushes frames through both bins, and _testGpuBinModeFromEnvironment\nchecks the parsing. _testDmaBufDispatch, which now reaches the direct\nbin, skips with the actual cause: no VA-API stack, a VA driver that\nexports only tiled DMABuf (Intel iHD refuses LINEAR), or the pipeline\nerror.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(VideoReceiver): hold RTP H.264/H.265 until a full parameter set\n\nJoining a stream mid-GOP, slices before the next SPS/PPS (VPS/SPS/PPS) can't\nbe decoded. With GStreamer 1.28, parsebin's h264parse (converting byte-stream\nto the avc that VideoToolbox requires) warns for every such slice and fails\nthe pipeline with \"No caps set\" whenever it pushes an access unit before it\nhas both SPS and PPS, which broke receiver start-up on macOS.\n\nThe depayloaders' wait-for-keyframe needs access-unit output, which parsebin's\nunlinked negotiation never selects. Their DELTA_UNIT flag isn't enough: a\nsliced encoder's IDR can be joined after its SPS/PPS. Passing parameter sets\nearly isn't either: macOS CI traces show a jitter buffer dropping the PPS and\nIDR of the first keyframe, after which h264parse pushed the lone SPS and\nfailed.\n\nSo gateOnParameterSets() holds the depayloader's byte-stream output: it keeps\nthe latest VPS/SPS/PPS, drops everything else, and at the first slice after a\nfull set emits the stored sets with that slice in one buffer (the slice's\ntimestamps), then removes itself. No IDR is required, so intra-refresh streams\nstill start; length-prefixed output keeps its parameter sets in codec_data and\nis left alone.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* test(VideoReceiver): share GStreamer test helpers and a receiver fixture\n\nTest cleanup, part one (simplify-tests items in brackets).\n\n- GStreamerTest, GstVideoReceiverTest, GstVideoReceiverComponentsTest\n  and VideoManagerInitTest declare their slots only under\n  QGC_GST_STREAMING and a single _testGStreamerDisabled() otherwise,\n  replacing per-slot QSKIP stubs in three styles and a central list\n  that had fallen behind. (1)\n- runPipelineThroughQVideoSink()'s callers polled a by-value copy that\n  never changed, so delivery really depended on a fixed 50 ms drain.\n  The helper waits for a delivered frame, and the other hand-rolled\n  drains become condition or signal waits. (B2, B5)\n- GStreamerTestHelpers (GstTest) holds the shared init and skip reason,\n  firstMissingFactory(), a TestPipeline with TestTimeout defaults and\n  RAII teardown, and bin-walk, sample and Null-QRhi helpers. Both suites\n  call GStreamer::completeInit() once in initTestCase(). (2, 11, B1, B4)\n- GstVideoReceiverTest's StreamingReceiver fixture owns the port,\n  sender, widget, receiver and spies and resets the receiver before its\n  spies. Two tests are merged and one is split, and the new\n  _testDecodesMockLinkStreams decodes every MockVideoStreamServer\n  stream type MockLink advertises. (4, 5, 20, B9)\n- Shorter keyframe and quiet windows: keyframe interval 15 -> 5,\n  recorded frames 30 -> 15 and 1.2 s no-restart windows. Stress-checked\n  with 30 sequential and 2x15 concurrent runs. (3, 15, 16)\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* test(VideoReceiver): drop duplicate GStreamer tests, scope their refs\n\nTest cleanup, part two (simplify-tests items in brackets).\n\n- QgcQVideoSinkHarness sends stream-start, caps and segment itself; the\n  flush test runs on it deterministically instead of a 150 ms busy loop;\n  the preroll test folds into the latest-frame test; the two allocation\n  tests become one data-driven test; and the stats test keeps only the\n  behavioural guard. (6, 7, 12, 13, 14)\n- Duplicate tests and rows go, and the frame-texture tests move into\n  GStreamerHwFrameTexturesTest.cc, so the common file compiles again in\n  streaming builds without a GPU path. (8, 17, 18, 20)\n- The source-factory tests use firstMissingFactory() (the old checks\n  leaked the factory), GstElementPtr bins, findByFactory() and shared\n  fixtures, and the two udp265 tests merge. (9, 2)\n- The four D3D QRhi import copies become one data-driven test with a\n  createPublishedRhi() helper, and the Windows tests use EnvVarFixture\n  and LoggingCategoryFixture (the old code restored the wrong logging\n  rules). Syntax-checked with Q_OS_WIN forced. (19, B8)\n- Remaining manual unrefs use GstScoped owners (several tests leaked\n  their bin on a failed check), and each test file includes what it\n  uses. (B3, 10)\n- test/README.md: QVERIFY_SIGNAL_WAIT waits for a new emission, so\n  signals that may already have fired need QVERIFY_SIGNAL_COUNT_WAIT,\n  and a QSKIP in init() also skips cleanup(). (A1)\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* test(VideoReceiver): check the source bin holds RTP until parameter sets\n\nJoins a long-GOP H.264 RTP stream after its only keyframe and checks that no\nunit reaches h264parse until a forced keyframe, whose first unit carries the\nSPS. Drives gateOnParameterSets() directly through a lost-PPS late join:\nnothing passes on an SPS alone, and the first buffer out is SPS+PPS+IDR with\nthe IDR's timestamp; length-prefixed avc output passes untouched. Both fail\nwith the gate removed or passing parameter sets early.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(gstreamer): keep CMAKE_PREFIX_PATH out of the bundled SDK's lookups\n\nFindPkgConfig puts every CMAKE_PREFIX_PATH entry's pkgconfig directory in\nPKG_CONFIG_PATH, which pkg-config searches before the PKG_CONFIG_LIBDIR the\nSDK lock-in sets. Only the core targets were protected, by a function-local\nlist(PREPEND CMAKE_PREFIX_PATH <root>); the HwBuffers probes run later in\nanother directory, so a vcpkg/MSYS2 or Homebrew GStreamer in\nCMAKE_PREFIX_PATH supplied their D3D/Vulkan/CUDA headers and libraries.\n\n- gstreamer_apply_pkgconfig_env MODE SDK sets PKG_CONFIG_USE_CMAKE_PREFIX_PATH\n  OFF in the caller; the Windows, macOS and Android discovery functions\n  propagate it with their other pkg-config outputs, so the whole GStreamer\n  subtree inherits it.\n- Drop the PREPEND in _qgc_gst_create_sdk_targets. Its only effect was on\n  pkg-config: every find_library in that function's scope uses\n  NO_DEFAULT_PATH or looks up Apple system frameworks, and on Linux\n  (SYSTEM_AUGMENT) the SDK's pkgconfig directory already leads\n  PKG_CONFIG_PATH.\n- _qgc_probe_gst_lib's find_library skips CMAKE_PREFIX_PATH (cache and\n  environment) under the SDK lock-in; it is searched before HINTS.\n\nThe new sdk-prefix-decoy fixture scenario configures a fake Android SDK with\na decoy GStreamer prefix in CMAKE_PREFIX_PATH and probes an optional library\nas HwBuffers does. It fails without each of the three changes.\n\nFixes review3 A1/D1.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(gstreamer): trust SDK pins for SDK reuse and installers\n\nA pinned SDK package is verified against its in-tree pin whichever host\nserves it (upstream first, the QGC S3 mirror as fallback), so the pin\ncan decide more than the final hash check:\n\n- With GStreamer_REQUIRE_CHECKSUM=OFF the Windows extractor refused to\n  run any installer, even the default SDK just verified against its pin,\n  so the option made the Windows auto-download impossible. It now\n  refuses only an installer without a pin, since a sidecar does not\n  authenticate an executable that runs silently. (review3 A2)\n- Tree reuse (perf): every configure downloaded or re-hashed the archive\n  (~1 GB on Android) even when the cached tree was already stamped with\n  its checksum. qgc_gst_acquire_sdk builds the stamp from the pins first\n  and uses a matching tree as is. CI's SDK cache then stores only the\n  extracted trees, keyed on the build-config.json gstreamer section\n  (cpm_helper.py gstreamer-fingerprint), so Qt or NDK bumps no longer\n  invalidate it; the new key misses the existing caches once. (review3\n  D3, B8)\n\nTests: test_download checks the upstream-first URL order and the\nchecksum each package is held to, CMake.DownloadHelper holds fallback\nURLs to EXPECTED_HASH, test_windows_installer_guard runs a pinned\nstand-in installer with checksums off (failed before) and refuses an\nunpinned one, test_sdk_acquire reuses a pinned tree whose archive is\ngone, and test_cache_contracts and test_cpm_helper cover the cache.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* build(gstreamer): validate QGC_GST_VERSION and quiet configure output\n\n- QGC_GST_VERSION must be <major>.<minor>.<micro>: a partial version\n  such as 1.28 failed later with a misleading checksum error or after\n  six 404s. QGC_GST_CUDA_STUB_DIR is declared, BuildConfig.cmake stops\n  printing the default version as \"the\" GStreamer version, the install\n  code reads FRAMEWORK_BUNDLE through gstreamer_layout_get, and the\n  README gives the real 0.3-1 GB archive sizes. (review3 B10)\n- The registration shim, GStreamer.cc and the GStreamer CMakeLists\n  disagreed on why static plugin registration is guarded. Neither SDK\n  registers plugins itself: a static gst_init() calls any\n  gst_init_static_plugins() it can look up (gst/gst.c, 1.28.4), which\n  on Android finds QGC's function before _registerPlugins() calls it\n  again. All three comments now say so. (review3 B6)\n- Optional components are probed QUIET, so a configure without one\n  (every Linux Debug configure lacked gst-rtsp-server) no longer prints\n  pkg-config's \"not found\"; one status line lists the missing ones.\n  (review3 D7)\n- Missing plugins are classified: hardware and alternative decoders in\n  the new GSTREAMER_OPTIONAL_PLUGINS get one status line, allowlist\n  names the SDK doesn't ship at all get one warning pointing at\n  build-config.json, and plugins a static SDK ships but can't link keep\n  the old warning. Mobile builds still fail on a missing\n  runtime-required plugin. (review3 D8, B4, E6)\n\nTests: a version-format scenario, the missing-gl scenario's quiet probe,\ntest_plugin_policy's classification, test_plugin_scan's static scan and\na plugin-allowlist scenario that warns about a misspelled name alone.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* feat(gstreamer): ship GStreamer's LGPL text and notice and SBOM entry\n\nQGC bundles GStreamer on every platform (installed libraries and plugins on\nWindows, macOS and Linux; linked statically into the Android and iOS apps)\nbut shipped no licence text or notice for it, and its only third-party\nlicence handling was CPack's licence page for QGC's own COPYING.md. The\ndependency SBOM CI attaches to every package (generate_cpm_sbom.py, read\nfrom CMakeCache.txt) listed CPM packages only; syft's binary scan was the\nonly trace of GStreamer.\n\n- cmake/GStreamer/notice/LGPL-2.1.txt is the GNU LGPL 2.1 text (gnu.org,\n  page-break form feeds dropped by the whitespace hook). Notice.cmake writes\n  it with a NOTICE.txt naming the GStreamer version, the GStreamer source\n  tree of that version and, for an auto-downloaded SDK, the official\n  packages with their SHA-256 and the Cerbero release that built them. It\n  says that some plugins and the libraries they use have other licences\n  (each plugin declares its own) without listing any.\n- The Orchestrator writes them for every platform and records the directory\n  on GStreamer::Layout (NOTICE_DIR). Desktop installs copy them to\n  share/licenses/gstreamer (macOS: <app>.app/Contents/Resources/licenses/\n  gstreamer); Android stages them with the APK assets and iOS adds them as\n  bundle resources, both under licenses/gstreamer.\n- qgc_gst_acquire_sdk records the packages (QGC_GST_RESOLVED_PACKAGES) and\n  _qgc_gst_record_resolved_sdk the GStreamer version\n  (QGC_GST_RESOLVED_SDK_VERSION); a discovered SDK clears the packages.\n- generate_cpm_sbom.py adds GStreamer as a component (LGPL-2.1-or-later,\n  source tree, and each downloaded package as a distribution reference\n  with its SHA-256) when video streaming is enabled; the SPDX snapshot now\n  carries a component's declared licence.\n\nTests: test_notice (both notice forms), test_sdk_acquire and test_sdk_state\n(recorded packages and version), the install, install-macos and\nandroid-mobile fixture scenarios (shipped files), test_generate_cpm_sbom\n(component and SPDX licence).\n\nImplements review3 E1.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* build(deps): install the gst-rtsp-server headers on Linux\n\nDebug builds request gstreamer-rtsp-server-1.0 for MockLink's RTSP test\nstream (MockVideoStreamServer, QGC_GST_RTSP_SERVER), but no Linux setup\ninstalled it, so its five RTSP blocks were only ever compiled by the\nmacOS Debug job. Add the development package to the Debian/Ubuntu\n(libgstrtspserver-1.0-dev), Fedora (gstreamer1-rtsp-server-devel) and Arch\n(gst-rtsp-server) GStreamer lists that CI, Docker and the runner image\ninstall. The aarch64 cross sysroot list is left alone: its builds are\nRelease, which do not request the library.\n\nVerified on Ubuntu 24.04 with the 1.24.2 packages extracted into a\nscratch prefix: Debug configure finds the module, the build compiles the\nRTSP blocks with -Werror, and GStreamerTest, GstVideoReceiverTest,\nGstVideoReceiverComponentsTest, VideoManagerTest, VideoManagerInitTest,\nVideoManagerRestartTest and QGCVideoStreamInfoTest pass (7/7). No existing\ntest is gated on QGC_GST_RTSP_SERVER; a local, uncommitted harness started\nthe RTSP mock server and decoded its stream through rtspsrc.\n\nFixes review3 B3 (the probe noise part is in the QUIET components change).\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* build(gstreamer): tighten mobile SDK discovery and iOS archive linking\n\n- The iOS SDK version came from a GStreamer.framework Info.plist, which\n  an xcframework slice doesn't have, so it always ended in \"actual\n  version is UNVERIFIED\" and a downgraded SDK went undetected. It is\n  read from gst/gstversion.h (_qgc_gst_header_version), which also\n  gives the iOS SDK fingerprint a version; PlistBuddy is no longer used.\n  (review3 D2)\n- Android builds on a macOS host FORCE-cached Homebrew's pkg-config,\n  making Homebrew a prerequisite. The SDK ships a universal macOS\n  pkg-config in share/gst-android/ndk-build/tools/macos (checked in the\n  pinned 1.28.4 SDK), which is now used when present, as a normal\n  variable like the Windows one. (review3 D5)\n- On iOS GStreamer::GStreamer linked the merged archive, so a core\n  function QGC calls that no registered plugin pulls into the framework\n  was silently linked into the app, possibly with a second core.\n  GStreamer::GStreamer is now usage-only and GStreamerMobileXcfw links\n  the archive privately, so such a call fails the link naming the\n  symbol. qgc_gst_ios_keep_symbols() keeps the nine RTSP server\n  functions Debug's MockVideoStreamServer uses, IOSSingleCoreCheck stays\n  as the post-build guard, and the configure probe no longer links the\n  ~300 MB archive. (review3 D6, B9)\n\nTests: test_ios_sdk_version (slice, framework, fingerprint, unreadable\nheader, below-floor failure), test_android_pkg_config, and an ios-link\nfixture scenario that builds the real helpers against a fake merged\narchive on Linux and fails with the archive linked into\nGStreamer::GStreamer again. The real iOS link needs iOS CI.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* feat(video): give bundled desktop GStreamer runtimes a private registry\n\nA bundled runtime (Linux AppImage or install, Windows, macOS bundle) used\nGStreamer's default per-user registry, ~/.cache/gstreamer-1.0/\nregistry.<arch>.bin, which the system GStreamer and other bundles share.\nWith a different plugin set behind it, each of them invalidated the\nother's cache and forced a full rescan, and a registry written by another\nGStreamer version could be reused.\n\nWhen prepareEnvironment() points GStreamer at bundled plugins it now also\nsets GST_REGISTRY to gstreamer-<runtime version>-<arch>.bin in the app's\nQStandardPaths::CacheLocation, creating the directory, unless the user set\nGST_REGISTRY or GST_REGISTRY_1_0. Mobile builds keep their own registry\nand a system-GStreamer Linux build keeps the default. logDiagnostics()\nalso prints GST_REGISTRY.\n\nGStreamerEnvironmentTest (new, Unit) covers the registry path and\ndirectory, a user-set GST_REGISTRY or GST_REGISTRY_1_0 winning, and a\nsystem-GStreamer Linux build leaving GST_REGISTRY unset.\n\nImplements review3 E2.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* feat(gstreamer): add QGC_GST_BUNDLE_PLUGINS, trim bundled GIO modules\n\n- Linux installs bundled every module of the system GIO module\n  directory, gvfs's included, which the bundle never uses (it runs GIO\n  with GIO_USE_VFS=local). gstreamer_install_gio_modules takes a MODULES\n  allowlist, and Linux installs only the TLS backend, the proxy\n  resolvers and the dconf settings backend (libgiognutls,\n  libgiolibproxy, libgiognomeproxy, libdconfsettings). With a staged\n  install, GLib 2.80 loads the GnuTLS backend, both proxy resolvers and\n  DConf. Windows and macOS are unchanged. (review3 E4)\n- QGC_GST_BUNDLE_PLUGINS (Linux, default ON) lets distribution packages\n  use the system's plugins. OFF installs nothing of GStreamer and skips\n  the plugin verification, compiles GStreamerEnvironment.cc with\n  QGC_GST_SYSTEM_PLUGINS so the app never redirects GStreamer, makes the\n  Arch package depend on gst-plugins-good, gst-plugins-bad-libs and\n  gst-libav, and fails configure with QGC_CREATE_APPIMAGE. The summary\n  and the GStreamer README document it; a Debug configure, build and\n  install with OFF ran GStreamerTest (183 passed). (review3 E5)\n\nTests: the install scenario checks that only the four GIO modules are\nstaged and covers the OFF install (both fail without the change),\ntest_install_filter the explicit names, and\ntest_native_packaging_contract the Arch dependencies.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(HwBuffers): copy the last chroma of odd-width packed 4:2:2 rows\n\nGstHw::planeRowBytes() sized a row from the plane's first component alone.\nFor YUY2/UYVY that is luma, so an odd-width row stopped before its last\nchroma sample (a 5-pixel YUY2 row needs 12 bytes, not 10) and the CPU-copy\nfallback left the rightmost pixel's V unwritten. The row now ends at the\nfurthest byte any component of the plane reaches; planar and semi-planar\nformats are unchanged. The same first-component sizing was already on\nmaster.\n\nReported by Copilot review on #15304.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(VideoManager): give each video stream its own screenshot file\n\ngrabImage() handed every receiver the same file, so with a thermal stream\nrunning its screenshot overwrote the main one. That was latent while\nGStreamer screenshots were unimplemented and Qt Multimedia's always failed.\nLike recordings, streams other than the main one now get their name before\nthe extension (\u2026.thermalVideo.jpg), and receivers that aren't running are\nskipped instead of failing.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* fix(GraphicsSetup): configure the root window when its surface is created\n\nAndroid exposes a window synchronously when it is shown (QPlatformWindow::\nsetVisible flushes the expose event), and the root QML shows the window\nwhile it loads (visible: true, showFullScreen() on mobile). The threaded\nrender loop then initializes the scene graph inside load(), so the RHI\nconfiguration applied afterwards was skipped with \"Scene graph already\ninitialized before configureMainWindow\", and Android never got the\npipeline cache.\n\nGraphicsSetup::configureMainWindowOnCreation() now configures the first\nQQuickWindow from a one-shot application event filter on its\nSurfaceCreated event, which QWindow::create() sends before any expose on\nevery platform. configureMainWindow() also checks the window's own QRhi\ninstead of isSceneGraphInitialized(): the basic render loop shares one\nrender context, so a new window reported an initialized scene graph as\nsoon as another window had rendered.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* refactor(gstreamer): simplify the GStreamer CMake modules\n\nCut about 1200 lines from cmake/GStreamer and its tests without changing\nwhich SDK is found, downloaded, linked or bundled:\n\n- Components: one component list plus the mandatory set. An unknown\n  QGC_GST_COMPONENTS entry now fails configure instead of being ignored.\n- Layout: discovery derives one layout shape; GStreamer::Layout keeps only\n  what readers outside the Orchestrator need (FRAMEWORK_BUNDLE, NOTICE_DIR).\n  Discovery functions return through _qgc_gst_return_discovery().\n- Install and plugin-policy helpers take positional arguments; the system\n  prefix guard and the Windows libproxy backend lookup are shorter.\n- Windows: drop the nested SDK root search. No supported source (1.28+\n  download, tools/setup installer, official installer, GStreamer_ROOT_DIR)\n  produces a nested root.\n- iOS discovery and the Android archive lookup are consolidated.\n- The S3 mirror URL is derived from the package URL; the upstream\n  freedesktop.org URL is still tried first.\n- The SDK version comes from gst/gstversion.h, and the C++ code compares\n  GST_VERSION_MAJOR/MINOR directly instead of QGC_GST_BUILD_VERSION_*.\n- Shared argument validation (_qgc_gst_check_args) and test helpers\n  (qgc_test_split, qgc_test_assert_matches); Helpers.cmake is removed.\n\nTests for deleted code are removed: test_components_malformed (now\ntest_components.UnknownComponent), test_argument_validation.InstallUnknown,\ntest_plugin_policy_conflict (now asserted in test_plugin_policy) and\ntest_windows_runtime_libproxy.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n* feat(gstreamer): build against Homebrew's GStreamer on macOS when opted in\n\nmacOS discovery used /opt/homebrew/opt/gstreamer or /usr/local/opt/gstreamer\nwhenever no GStreamer.framework was installed, but it locked pkg-config to\nthe keg, which hides GLib and the macOS libffi/zlib shims gstreamer-1.0.pc\nrequires, so that configure always failed.\n\nHomebrew's GStreamer is now used only when asked for:\n- QGC_GST_USE_HOMEBREW=ON (default OFF) finds it with `brew --prefix\n  gstreamer`, else the default prefixes, ahead of a cached download.\n- GStreamer_ROOT_DIR set to a Homebrew prefix, or its opt/gstreamer or\n  Cellar/gstreamer/<version>, selects it too.\nIts modules are read with the prefix's own pkg-config (Homebrew's pkgconf\nsearches the shims), with the keg, the prefix and opt/glib added so an\nunlinked formula works. Without the option the order is unchanged:\nGStreamer_ROOT_DIR, an earlier download, the installed framework, a new\ndownload.\n\nHomebrew's libraries and plugins load each other by absolute paths, so\nsuch a build runs from the build tree only: install and packaging now fail\nwith an explanation instead of bundling an app that loads Homebrew's files.\n\nGStreamer.test_orchestrator.homebrew covers linked and unlinked prefixes,\nprecedence over a cached SDK and the install refusal.\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n\n---------\n\nCo-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>\n"
]
  assert.equal(await analyze(messages), 'minor')
})

test('all configured plugins resolve from the isolated release directory', async () => {
  const { default: getConfig } = await import('./node_modules/semantic-release/lib/get-config.js')
  const logger = { log() {}, success() {}, warn() {}, error() {} }
  const { plugins } = await getConfig({ cwd, env: process.env, logger }, { extends: '../../.releaserc.json' })
  assert.equal(typeof plugins.verifyRelease, 'function')
  assert.equal(typeof plugins.publish, 'function')
})
